function act(obs, mem) {
    if (!mem.init) {
        mem.init = 1;
        mem.pos = [];
        mem.stuck = 0;
        mem.maneuver = 0;
        mem.side = 1;
        mem.prevSteer = 0;
        mem.idx = obs.targetIndex;
    }

    // Stuck detection via position history (catches oscillation too)
    mem.pos.push([obs.x, obs.y]);
    if (mem.pos.length > 30) mem.pos.shift();
    let stuckness = false;
    if (mem.pos.length >= 30) {
        let netD = Math.hypot(obs.x - mem.pos[0][0], obs.y - mem.pos[0][1]);
        let totD = 0;
        for (let i = 1; i < mem.pos.length; i++) {
            totD += Math.hypot(mem.pos[i][0] - mem.pos[i-1][0], mem.pos[i][1] - mem.pos[i-1][1]);
        }
        stuckness = (netD < 0.3 && obs.t > 1.5) || (totD > 1.0 && netD / (totD + 0.001) < 0.15);
    }
    mem.stuck = stuckness ? mem.stuck + 1 : Math.max(0, mem.stuck - 1);
    if (obs.targetIndex > mem.idx) {
        mem.idx = obs.targetIndex;
        mem.stuck = 0;
    }

    // Target direction from GPS
    const dx = obs.targetX - obs.x;
    const dy = obs.targetY - obs.y;
    const dist = Math.hypot(dx, dy);
    let bearing = Math.atan2(dy, dx) * 180 / Math.PI;
    let err = ((bearing - obs.heading + 540) % 360) - 180;

    // Sensor analysis: rays at [-60,-30,0,30,60] deg relative to heading
    const r = obs.rays.map(v => Math.min(v, 10));
    const SAFE = 2.0;

    let avoid = 0, danger = 0;
    for (let i = 0; i < 5; i++) {
        if (r[i] < SAFE) {
            const w = (SAFE - r[i]) / SAFE;
            const ww = w * w;
            danger = Math.max(danger, ww);
            // Repel from obstacle: right (i<2) steer left (+), left (i>2) steer right (-)
            if (i < 2) avoid += ww * (1.3 - i * 0.3);
            if (i > 2) avoid -= ww * (1.3 - (4 - i) * 0.3);
        }
    }

    // Front blocked → prefer side with more clearance
    if (r[2] < 1.5) {
        const ls = Math.min(r[3], r[4]);
        const rs = Math.min(r[0], r[1]);
        avoid += (ls > rs ? 1 : -1) * 1.5 * ((1.5 - r[2]) / 1.5);
        mem.side = ls > rs ? 1 : -1;
    }

    // Gap centering when flanked by obstacles
    if (r[1] < 2.5 || r[3] < 2.5) {
        avoid += Math.max(-0.6, Math.min(0.6, (r[3] - r[1]) * 0.15));
    }
    avoid = Math.max(-2, Math.min(2, avoid));

    // Stuck recovery: back up → pivot turn → go forward
    if (mem.stuck > 15) {
        mem.maneuver = 55;
        mem.stuck = 0;
    }
    if (mem.maneuver > 0) {
        mem.maneuver--;
        if (mem.maneuver > 40) return {left: -0.5, right: -0.5};
        if (mem.maneuver > 15) {
            const s = mem.side * 0.65;
            return {left: -s, right: s};
        }
        return {left: 0.6, right: 0.6};
    }

    // Large error → pivot turn toward target
    if (Math.abs(err) > 110) {
        const s = Math.sign(err) * 0.6;
        return {left: -s, right: s};
    }

    // Steering: smooth blend of target attraction and obstacle avoidance
    const obsInfluence = Math.min(1, danger * 3 + Math.abs(avoid) * 0.3);
    let steer = err * (1 - obsInfluence * 0.6) + avoid * 40 * obsInfluence;
    steer = Math.max(-120, Math.min(120, steer));

    // PD control for smooth turning
    const dS = steer - mem.prevSteer;
    mem.prevSteer = steer;
    let turn = steer * 0.012 + dS * 0.01;
    turn = Math.max(-0.8, Math.min(0.8, turn));

    // Dead-zone override for small turns when correction is needed
    if (Math.abs(steer) > 10 && Math.abs(turn) < 0.12 && Math.abs(turn) > 0.01) {
        turn = Math.sign(turn) * 0.12;
    }

    // Speed modulation
    let speed = 1.0;
    if (danger > 0.05) speed *= Math.max(0.1, 1 - danger * 1.5);
    if (Math.abs(steer) > 50) speed *= 0.25;
    else if (Math.abs(steer) > 25) speed *= 0.5;
    if (dist < 3) speed *= Math.max(0.2, dist / 3);

    // Scale commands to fit [-1,1] preserving turn ratio
    let l = speed - turn;
    let r2 = speed + turn;
    const mx = Math.max(Math.abs(l), Math.abs(r2));
    if (mx > 1) { l /= mx; r2 /= mx; }

    return {
        left: Math.max(-1, Math.min(1, l)),
        right: Math.max(-1, Math.min(1, r2))
    };
}

