    if (r[1] < 2.5) { const w = (2.5 - r[1]) / 2.5; aTurn += w * w * 0.15; danger = Math.max(danger, w * 0.6); }
    if (r[2] < 3.0) { danger = Math.max(danger, Math.min(1, (3.0 - r[2]) / 2.0)); }
    if (r[3] < 2.5) { const w = (2.5 - r[3]) / 2.5; aTurn -= w * w * 0.15; danger = Math.max(danger, w * 0.6); }
    if (r[4] < 2.5) { const w = (2.5 - r[4]) / 2.5; aTurn -= w * w * 0.3; danger = Math.max(danger, w); }

    if (r[2] < 2.0) {
        mem.ms = (r[3] + r[4]) >= (r[0] + r[1]) ? 1 : -1;
        aTurn += mem.ms * 0.3;
    }

    if (r[1] < 3.0 && r[3] < 3.0) {
        aTurn += (r[3] - r[1]) * 0.04;
    }

    if (Math.abs(herr) > 60) {
        return {left: -Math.sign(herr) * 0.15, right: Math.sign(herr) * 0.15};
    }

    let pgain = 0.003;
    if (dist < 3) pgain *= Math.max(0.3, dist / 3);
    let turn = herr * pgain + aTurn;
    turn = Math.max(-0.15, Math.min(0.15, turn));

    let fwd = 0.5;
    if (danger > 0.3) fwd = 0.15;
    else if (danger > 0.1) fwd = 0.3;
    if (Math.abs(herr) > 30) fwd *= 0.5;
    if (dist < 2) fwd *= Math.max(0.1, dist / 2);

    return {
        left: Math.max(-1, Math.min(1, fwd - turn)),
        right: Math.max(-1, Math.min(1, fwd + turn))
    };
}

