    while (mem.h.length > 40) mem.h.shift();
    if (mem.h.length >= 35 && obs.t > 2 && mem.cd <= 0) {
        const nd = Math.hypot(obs.x - mem.h[0][0], obs.y - mem.h[0][1]);
        mem.sk = nd < 0.4 ? mem.sk + 1 : Math.max(0, mem.sk - 3);
    }

    // Rays
