    let minR = 10;
    for (let i = 0; i < 5; i++) minR = Math.min(minR, r[i]);

    // Dead-end / trapped detection
    const trapped = r[2] < 1.0 && r[1] < 2.5 && r[3] < 2.5 && r[0] < 3 && r[4] < 3;
    if ((mem.sk > 15 || trapped) && mem.rv <= 0 && mem.cd <= 0) {
        mem.rv = 65;
        mem.rs = (r[3] + r[4] + 1) >= (r[0] + r[1]) ? 1 : -1;
        mem.sk = 0;
        mem.cd = 50;
    }

    // Recovery execution
    if (mem.rv > 0) {
        mem.rv--;
        if (mem.cd > 0) mem.cd--;
        if (mem.rv > 45) return { left: -0.5, right: -0.5 };
        if (mem.rv > 18) return { left: -mem.rs * 0.55, right: mem.rs * 0.55 };
        return { left: 0.35, right: 0.35 };
    }
    if (mem.cd > 0) mem.cd--;

    // Target direction
