        return { left: -Math.sign(herr) * ta, right: Math.sign(herr) * ta };
    }

    // Side wall memory - remember walls even when sensors lose sight
    if (r[0] < 2.5 || r[1] < 1.8) mem.sR = 30;
    if (r[4] < 2.5 || r[3] < 1.8) mem.sL = 30;
    if (mem.sR > 0) mem.sR--;
    if (mem.sL > 0) mem.sL--;

