    if (r[2] < 5 && mem.at <= 0) {
        mem.ad = (r[3] + r[4] + 1) > (r[0] + r[1]) ? 1 : -1;
        mem.at = 55;
    }
    if (mem.at > 0) mem.at--;
    if (r[2] < 5) {
        const w = (5 - r[2]) / 5;
        avoid += mem.ad * w * w * 1.5;
    }

    // Side avoidance
    if (r[0] < 3) { const w = (3 - r[0]) / 3; avoid += w * w * 0.8; }
    if (r[1] < 2.5) { const w = (2.5 - r[1]) / 2.5; avoid += w * w * 0.4; }
    if (r[3] < 2.5) { const w = (2.5 - r[3]) / 2.5; avoid -= w * w * 0.4; }
    if (r[4] < 3) { const w = (3 - r[4]) / 3; avoid -= w * w * 0.8; }

    // Side wall memory avoidance
    if (mem.sR > 0) avoid += 0.15;
    if (mem.sL > 0) avoid -= 0.15;

    // Corridor centering
    if (r[1] < 3 && r[3] < 3) avoid += (r[3] - r[1]) * 0.15;

    avoid = Math.max(-1, Math.min(1, avoid));

    // Steering
    let turn = herr * 0.007 + avoid * 0.4;
    turn = Math.max(-0.5, Math.min(0.5, turn));

    // Speed control
    let fwd = 0.9;
    if (minR < 0.8) fwd = 0.05;
    else if (minR < 1.5) fwd = 0.15;
    else if (minR < 2.5) fwd = 0.3;
    else if (minR < 4) fwd = 0.55;

    if (Math.abs(herr) > 60) fwd = Math.min(fwd, 0.1);
    else if (Math.abs(herr) > 35) fwd = Math.min(fwd, 0.35);

    if (dist < 2) fwd *= Math.max(0.2, dist / 2);

    // Motor output
    let l = fwd - turn;
    let rt = fwd + turn;
    const mx = Math.max(Math.abs(l), Math.abs(rt));
    if (mx > 1) { l /= mx; rt /= mx; }
    return { left: l, right: rt };
}

