  mem.rayFilter = rayFilter;

  function cellX(wx) {
    return clamp(Math.floor(wx / CELL), 0, N - 1);
  }

  function cellY(wy) {
    return clamp(Math.floor(wy / CELL), 0, N - 1);
  }

  function setFree(gx, gy) {
    if (gx < 0 || gy < 0 || gx >= N || gy >= N) return;
    const k = gy * N + gx;
    if (mem.map[k] === 0) mem.map[k] = 1;
  }

  function setOccupied(gx, gy) {
    if (gx < 0 || gy < 0 || gx >= N || gy >= N) return;
    const k = gy * N + gx;
    if (mem.map[k] !== 2) {
      mem.map[k] = 2;
      mem.mapDirty = true;
    }
  }

  if (finite(mem.trailX) && finite(mem.trailY)) {
    const dx = x - mem.trailX;
    const dy = y - mem.trailY;
    const distance = Math.hypot(dx, dy);

    if (distance < 2.5) {
      const steps = Math.max(1, Math.ceil(distance / 0.20));
      for (let j = 0; j <= steps; j++) {
        const q = j / steps;
        setFree(
          cellX(mem.trailX + dx * q),
          cellY(mem.trailY + dy * q)
        );
      }
    }
  }

  setFree(cellX(x), cellY(y));
  mem.trailX = x;
  mem.trailY = y;

  for (let i = 0; i < 5; i++) {
    const a = rad(heading + rayAngles[i]);
    const ca = Math.cos(a);
    const sa = Math.sin(a);

    const raw = rawRays[i];
    const hit = raw < 9.70;
    const freeDistance = hit
      ? Math.max(0.05, raw - 0.52)
      : 9.15;

    for (let d = 0.15; d <= freeDistance; d += 0.25) {
      setFree(
        cellX(x + ca * d),
        cellY(y + sa * d)
      );
    }

    if (hit) {
      const obstacleDistance = Math.max(
        0.10,
        raw - 0.18
      );
      const gx = cellX(x + ca * obstacleDistance);
      const gy = cellY(y + sa * obstacleDistance);

      for (let oy = -1; oy <= 1; oy++) {
        for (let ox = -1; ox <= 1; ox++) {
          setOccupied(gx + ox, gy + oy);
        }
      }
    }
  }

  let targetIndex = finite(obs.targetIndex)
    ? Math.max(0, Math.floor(obs.targetIndex))
    : (mem.targetIndex === null ? 0 : mem.targetIndex);

  let targetX = finite(obs.targetX) ? obs.targetX : NaN;
  let targetY = finite(obs.targetY) ? obs.targetY : NaN;

  const targetList = obs.targets;
  const targetEntry =
    targetList && targetList[targetIndex] !== undefined
      ? targetList[targetIndex]
      : null;

  if (targetEntry) {
    if (Array.isArray(targetEntry)) {
      if (!finite(targetX) && finite(targetEntry[0])) {
        targetX = targetEntry[0];
      }
      if (!finite(targetY) && finite(targetEntry[1])) {
        targetY = targetEntry[1];
      }
    } else {
      if (!finite(targetX) && finite(targetEntry.x)) {
        targetX = targetEntry.x;
      }
      if (!finite(targetY) && finite(targetEntry.y)) {
        targetY = targetEntry.y;
      }
      if (!finite(targetX) && finite(targetEntry[0])) {
        targetX = targetEntry[0];
      }
      if (!finite(targetY) && finite(targetEntry[1])) {
        targetY = targetEntry[1];
      }
    }
  }

  if (!finite(targetX) || !finite(targetY)) {
    const gx = finite(obs.goalX) ? obs.goalX : NaN;
    const gy = finite(obs.goalY) ? obs.goalY : NaN;
    const left = finite(obs.targetsLeft)
      ? obs.targetsLeft
      : NaN;

    if (
      finite(gx) &&
      finite(gy) &&
      (
        !finite(left) ||
        left <= 0 ||
        !targetList ||
        targetIndex >= targetList.length
      )
    ) {
      targetX = gx;
      targetY = gy;
    }
  }

  if (!finite(targetX) || !finite(targetY)) {
    return send(0, 0, true);
  }

  const targetDistance = Math.hypot(
    targetX - x,
    targetY - y
  );

  const targetChanged =
    mem.targetIndex === null ||
    mem.targetIndex !== targetIndex ||
    !finite(mem.seenTargetX) ||
    !finite(mem.seenTargetY) ||
    Math.hypot(
      targetX - mem.seenTargetX,
      targetY - mem.seenTargetY
    ) > 0.75;

  if (targetChanged) {
    mem.targetIndex = targetIndex;
    mem.seenTargetX = targetX;
    mem.seenTargetY = targetY;

    mem.plan = null;
    mem.lastPlan = -1e9;
    mem.planRetry = -1e9;
    mem.mapDirty = true;

    mem.avoid = false;
    mem.avoidCooldown = 0;
    mem.recoverStage = 0;
    mem.hardSince = null;

    mem.bias = mem.bias >= 0 ? -1 : 1;

    mem.bestTargetDist = targetDistance;
    mem.progressT = now;
    mem.progressSampleT = now;
    mem.progressSampleX = x;
    mem.progressSampleY = y;
    mem.motionSampleT = now;
    mem.motionSampleX = x;
    mem.motionSampleY = y;
  }

  function makePlan(goalWorldX, goalWorldY) {
    const total = N * N;

    const startGX = clamp(
      cellX(x),
      2,
      N - 5
    );
    const startGY = clamp(
      cellY(y),
      2,
      N - 5
    );

    const goalGX = clamp(
      cellX(goalWorldX),
      2,
      N - 5
    );
    const goalGY = clamp(
      cellY(goalWorldY),
      2,
      N - 5
    );

    const start = startGY * N + startGX;
    const goal = goalGY * N + goalGX;

    const gScore = new Float32Array(total);
    gScore.fill(1e9);

    const parent = new Int32Array(total);
    parent.fill(-1);

    const closed = new Uint8Array(total);
    const heapIds = [];
    const heapF = [];

    function heapPush(id, f) {
      let i = heapIds.length;
      heapIds.push(id);
      heapF.push(f);

      while (i > 0) {
        const p = (i - 1) >> 1;
        if (heapF[p] <= f) break;

        heapIds[i] = heapIds[p];
        heapF[i] = heapF[p];
        i = p;
      }

      heapIds[i] = id;
      heapF[i] = f;
    }

    function heapPop() {
      if (heapIds.length === 0) return -1;

      const result = heapIds[0];
      const lastId = heapIds.pop();
      const lastF = heapF.pop();

      if (heapIds.length > 0) {
        let i = 0;

        while (true) {
          const left = i * 2 + 1;
          if (left >= heapIds.length) break;

          const right = left + 1;
          let child = left;

          if (
            right < heapIds.length &&
            heapF[right] < heapF[left]
          ) {
            child = right;
          }

          if (heapF[child] >= lastF) break;

          heapIds[i] = heapIds[child];
          heapF[i] = heapF[child];
          i = child;
        }

        heapIds[i] = lastId;
        heapF[i] = lastF;
      }

      return result;
    }

    function heuristic(id) {
      const gx = id % N;
      const gy = Math.floor(id / N);
      const dx = goalGX - gx;
      const dy = goalGY - gy;
      return Math.sqrt(dx * dx + dy * dy);
    }

    const dxs = [-1, 0, 1, -1, 1, -1, 0, 1];
    const dys = [-1, -1, -1, 0, 0, 1, 1, 1];

    gScore[start] = 0;
    heapPush(start, heuristic(start));

    let found = false;
    let iterations = 0;

    while (
      heapIds.length > 0 &&
      iterations++ < 9000
    ) {
      const current = heapPop();

      if (current < 0 || closed[current]) continue;

      closed[current] = 1;

      if (current === goal) {
        found = true;
        break;
      }

      const cx = current % N;
      const cy = Math.floor(current / N);

      for (let di = 0; di < 8; di++) {
        const nx = cx + dxs[di];
        const ny = cy + dys[di];

        if (nx < 0 || ny < 0 || nx >= N || ny >= N) {
          continue;
        }

        const next = ny * N + nx;

        if (next !== goal && mem.map[next] === 2) {
          continue;
        }

        if (dxs[di] !== 0 && dys[di] !== 0) {
          const sideA = cy * N + (cx + dxs[di]);
          const sideB = (cy + dys[di]) * N + cx;

          if (
            (sideA !== goal && mem.map[sideA] === 2) ||
            (sideB !== goal && mem.map[sideB] === 2)
          ) {
            continue;
          }
        }

        const diagonal =
          dxs[di] !== 0 && dys[di] !== 0;

        const stepCost = diagonal ? 1.41421356 : 1;
        const terrainCost = mem.map[next] === 0 ? 1.12 : 1;
        const tentative =
          gScore[current] + stepCost * terrainCost;

        if (tentative < gScore[next]) {
          gScore[next] = tentative;
          parent[next] = current;
          heapPush(
            next,
            tentative + heuristic(next)
          );
        }
      }
    }

    if (!found) return null;

    const reversePath = [];
    let q = goal;

    for (let i = 0; i <= total; i++) {
      reversePath.push(q);

      if (q === start) break;

      q = parent[q];
      if (q < 0) return null;
    }

    if (
      reversePath.length === 0 ||
      reversePath[reversePath.length - 1] !== start
    ) {
      return null;
    }

    reversePath.reverse();

    let look = Math.min(
      reversePath.length - 1,
      6
    );

    if (reversePath.length > 18) {
      look = Math.min(reversePath.length - 1, 7);
    }

    const waypointCell = reversePath[look];
    const wx = waypointCell % N;
    const wy = Math.floor(waypointCell / N);

    return {
      x: (wx + 0.5) * CELL,
      y: (wy + 0.5) * CELL,
      goalX: goalWorldX,
      goalY: goalWorldY
    };
  }

  if (targetDistance > 1.35) {
    let needPlan = false;

    if (!mem.plan) {
      if (now >= mem.planRetry) needPlan = true;
    } else if (
      Math.hypot(
        x - mem.plan.x,
        y - mem.plan.y
      ) < 0.72
    ) {
      needPlan = true;
    } else if (
      Math.hypot(
        targetX - mem.plan.goalX,
        targetY - mem.plan.goalY
      ) > 0.75
    ) {
      needPlan = true;
    } else if (
      mem.mapDirty &&
      now - mem.lastPlan > 0.45
    ) {
      needPlan = true;
    }

    if (needPlan) {
      mem.plan = makePlan(targetX, targetY);
      mem.lastPlan = now;
      mem.planRetry = now + 0.65;
      mem.mapDirty = false;
    }
  } else {
    mem.plan = null;
  }

  let navX = targetX;
  let navY = targetY;

  if (mem.plan && targetDistance > 1.40) {
    const waypointDistance = Math.hypot(
      mem.plan.x - x,
      mem.plan.y - y
    );

    if (waypointDistance > 0.62) {
      navX = mem.plan.x;
      navY = mem.plan.y;
    }
  }

  const navAbsolute =
    Math.atan2(navY - y, navX - x) * 180 / Math.PI;

  const navAngle = wrap(
    navAbsolute - heading
  );

  const dampedAngle = navAngle -
    0.10 * clamp(mem.turnRate, -240, 240);

  const targetTurn = clamp(
    dampedAngle / 105,
    -1,
    1
  );

  if (
    targetDistance <
    mem.bestTargetDist - 0.08
  ) {
    mem.bestTargetDist = targetDistance;
    mem.progressT = now;
  }

  if (
    finite(mem.progressSampleT) &&
    now - mem.progressSampleT > 0.85
  ) {
    const moved = Math.hypot(
      x - mem.progressSampleX,
      y - mem.progressSampleY
    );

    if (moved > 0.38) {
      mem.progressT = now;
    }

    mem.progressSampleT = now;
    mem.progressSampleX = x;
    mem.progressSampleY = y;
  }

  if (
    finite(mem.motionSampleT) &&
    now - mem.motionSampleT > 0.95
  ) {
    const moved = Math.hypot(
      x - mem.motionSampleX,
      y - mem.motionSampleY
    );

    if (moved > 0.32) {
      mem.progressT = now;
    }

    mem.motionSampleT = now;
    mem.motionSampleX = x;
    mem.motionSampleY = y;
  }

  function danger(value, limit) {
    return clamp((limit - value) / limit, 0, 1);
  }

  const rightRisk = clamp(
    0.50 * danger(sensed[0], 1.45) +
    0.95 * danger(sensed[1], 2.25),
    0,
    1.5
  );

  const leftRisk = clamp(
    0.50 * danger(sensed[4], 1.45) +
    0.95 * danger(sensed[3], 2.25),
    0,
    1.5
  );

  const clearRight =
    0.58 * sensed[1] + 0.42 * sensed[0];

  const clearLeft =
    0.58 * sensed[3] + 0.42 * sensed[4];

  let front = sensed[2];

  if (sensed[1] < 0.85) {
    front = Math.min(front, sensed[1] + 0.35);
  }

  if (sensed[3] < 0.85) {
    front = Math.min(front, sensed[3] + 0.35);
  }

  const sideTurn = clamp(
    0.62 * (rightRisk - leftRisk),
    -0.7,
    0.7
  );

  const triggerDistance = clamp(
    2.10 + 0.20 * Math.max(0, speed),
    2.10,
    2.70
  );

  const frontBlocked =
    front < triggerDistance &&
    (
      Math.abs(navAngle) < 120 ||
      front < 1.05
    );

  if (front < 0.72) {
    if (mem.hardSince === null || !finite(mem.hardSince)) {
      mem.hardSince = now;
    }
  } else if (front > 1.02) {
    mem.hardSince = null;
  }

  function enterAvoid() {
    let leftScore = clearLeft;
    let rightScore = clearRight;

    const targetWeight = front < 1.35 ? 0.55 : 1.25;

    if (navAngle > 15) {
      leftScore += targetWeight;
    } else if (navAngle < -15) {
      rightScore += targetWeight;
    }

    let sign;

    if (Math.abs(leftScore - rightScore) < 0.30) {
      sign = mem.bias >= 0 ? 1 : -1;
    } else {
      sign = leftScore > rightScore ? 1 : -1;
    }

    mem.bias = mem.bias >= 0 ? -1 : 1;

    mem.avoid = true;
    mem.avoidSign = sign;
    mem.avoidStart = now;
    mem.avoidHitX = x;
    mem.avoidHitY = y;
    mem.avoidBest = targetDistance;
    mem.avoidFlipT = -1e9;
  }

  if (
    mem.avoid &&
    now - mem.avoidStart > 0.70 &&
    front > 2.70 &&
    sensed[2] > 2.25 &&
    (
      Math.abs(navAngle) < 125 ||
      targetDistance < 2
    )
  ) {
    mem.avoid = false;
    mem.avoidCooldown = now + 0.55;
  }

  if (
    !mem.avoid &&
    now >= mem.avoidCooldown &&
    frontBlocked &&
    (
      targetDistance > 1.08 ||
      front < 0.85
    )
  ) {
    enterAvoid();
  }

  if (
    mem.avoid &&
    targetDistance < mem.avoidBest
  ) {
    mem.avoidBest = targetDistance;
  }

  if (mem.avoid) {
    const age = now - mem.avoidStart;
    const loopDistance = Math.hypot(
      x - mem.avoidHitX,
      y - mem.avoidHitY
    );

    const chosenClear =
      mem.avoidSign > 0 ? clearLeft : clearRight;
    const otherClear =
      mem.avoidSign > 0 ? clearRight : clearLeft;

    if (
      age > 0.85 &&
      now - mem.avoidFlipT > 1.0 &&
      front < 1.45 &&
      chosenClear < 0.95 &&
      otherClear > chosenClear + 0.9
    ) {
      mem.avoidSign = -mem.avoidSign;
      mem.avoidFlipT = now;
    }
  }

  let requestRecovery = false;

  if (
    mem.avoid &&
    targetDistance > 1.25
  ) {
    const age = now - mem.avoidStart;
    const loopDistance = Math.hypot(
      x - mem.avoidHitX,
      y - mem.avoidHitY
    );

    if (
      age > 6.5 &&
      loopDistance < 1.45 &&
      targetDistance <= mem.avoidBest + 0.20 &&
      now - mem.progressT > 3.0
    ) {
      requestRecovery = true;
    }
  }

  if (
    mem.hardSince !== null &&
    finite(mem.hardSince) &&
    now - mem.hardSince > 1.05 &&
    Math.abs(speed) < 0.33 &&
    targetDistance > 1.20
  ) {
    requestRecovery = true;
  }

  if (
    !mem.avoid &&
    now - mem.progressT > 7.0 &&
    targetDistance > 2.0 &&
    Math.abs(navAngle) < 125 &&
    Math.abs(speed) < 0.35
  ) {
    requestRecovery = true;
  }

  function recoveryOutput() {
    const sign = mem.recoverSign >= 0 ? 1 : -1;

    let drive = 0;
    let turnNorm = sign;

    if (mem.recoverStage === 1) {
      if (front > 0.78) drive = -0.22;
      turnNorm = 0.72 * sign;
    }

    const turnPower = 0.43;

    return send(
      drive - turnPower * turnNorm,
      drive + turnPower * turnNorm,
      true
    );
  }

  if (mem.recoverStage) {
    if (now >= mem.recoverUntil) {
      if (mem.recoverStage === 1) {
        mem.recoverStage = 2;
        mem.recoverUntil = now + 0.68;
      } else {
        const oldSign =
          mem.avoidSign >= 0 ? 1 : -1;

        mem.recoverStage = 0;
        mem.avoid = true;
        mem.avoidSign = -oldSign;
        mem.avoidStart = now;
        mem.avoidHitX = x;
        mem.avoidHitY = y;
        mem.avoidBest = targetDistance;
        mem.avoidCooldown = 0;
        mem.plan = null;
        mem.mapDirty = true;
        mem.progressT = now;
      }
    }

    if (mem.recoverStage) {
      return recoveryOutput();
    }
  }

  if (requestRecovery && !mem.recoverStage) {
    mem.recoverStage = 1;
    mem.recoverSign = mem.avoid
      ? -mem.avoidSign
      : (navAngle >= 0 ? 1 : -1);
    mem.recoverUntil = now + 0.28;
    mem.avoid = true;

    return recoveryOutput();
  }

  let turnNorm;

  if (mem.avoid) {
    const urgency = clamp(
      (2.55 - front) / 1.75,
      0,
      1
    );

    if (front < 1.05) {
      turnNorm =
        mem.avoidSign * 0.96 +
        sideTurn * 0.25 +
        targetTurn * 0.08;
    } else {
      turnNorm =
        mem.avoidSign * (0.42 + 0.42 * urgency) +
        sideTurn * 0.48 +
        targetTurn * 0.16;
    }
  } else {
    turnNorm = targetTurn + 0.55 * sideTurn;
  }

  turnNorm = clamp(turnNorm, -1, 1);

  const angleMagnitude = Math.abs(navAngle);

  let desiredSpeed = mem.avoid ? 1.00 : 1.45;
  let drive = 0.68;

  if (finite(speed)) {
    drive += clamp(
      (desiredSpeed - speed) * 0.12,
      -0.18,
      0.16
    );
  }

  drive = clamp(
    drive,
    mem.avoid ? 0.10 : 0.12,
    mem.avoid ? 0.58 : 0.78
  );

  if (angleMagnitude > 135) {
    drive = 0.025;
  } else if (angleMagnitude > 112) {
    drive *= 0.12;
  } else if (angleMagnitude > 90) {
    drive *= 0.28;
  } else if (angleMagnitude > 60) {
    drive *= 0.62;
  } else if (angleMagnitude > 35) {
    drive *= 0.84;
  }

  if (front < 3.7) {
    drive *= clamp(
      (front - 0.55) / 3.15,
      0.04,
      1
    );
  }

  const strongestSideRisk = Math.max(
    leftRisk,
    rightRisk
  );

  if (strongestSideRisk > 0.55) {
    drive *= clamp(
      1 - 0.20 * strongestSideRisk,
      0.64,
      1
    );
  }

  if (mem.avoid) {
    drive = Math.min(drive, 0.56);
  }

  if (targetDistance < 3.0) {
    drive *= clamp(
      (targetDistance - 0.50) / 2.50,
      0.25,
      1
    );
  }

  if (
    finite(speed) &&
    speed > 1.9 &&
    front < 2.6
  ) {
    drive = Math.min(drive, 0.28);
  }

  if (front < 0.70) {
    drive = 0;
  }

  let turnPower = mem.avoid ? 0.45 : 0.42;

  if (angleMagnitude > 110 || front < 1.0) {
    turnPower = 0.47;
  }

  const leftCommand =
    drive - turnPower * turnNorm;
  const rightCommand =
    drive + turnPower * turnNorm;

  const urgent =
    front < 1.05 ||
    (mem.avoid && front < 1.35) ||
    angleMagnitude > 145;

  return send(
    leftCommand,
    rightCommand,
    urgent
  );
}

function act(obs, mem) {
  obs = obs || {};
  mem = mem || {};

  const finite = v => typeof v === "number" && isFinite(v);
  const clamp = (v, lo, hi) => v < lo ? lo : (v > hi ? hi : v);
  const wrap = a => {
    while (a > 180) a -= 360;
    while (a < -180) a += 360;
    return a;
  };
  const rad = a => a * Math.PI / 180;

  const VERSION = 33;
  const N = 80;
  const CELL = 0.5;
  const now = finite(obs.t) ? obs.t : 0;

  let x = finite(obs.x)
    ? obs.x
    : (finite(mem.lastX) ? mem.lastX : 20);
  let y = finite(obs.y)
    ? obs.y
    : (finite(mem.lastY) ? mem.lastY : 20);

  const speed = finite(obs.speed) ? obs.speed : 0;
  const speedAbs = Math.abs(speed);

  const initialHeading = finite(obs.heading)
    ? wrap(obs.heading)
    : (finite(mem.lastSensorHeading) ? mem.lastSensorHeading : 0);

  const fresh =
    mem._aeControllerVersion !== VERSION ||
    !mem.map ||
    mem.map.length !== N * N ||
    !mem.hitCount ||
    (finite(mem.lastCallT) && now < mem.lastCallT - 0.3);

  if (fresh) {
    mem._aeControllerVersion = VERSION;

    mem.map = new Uint8Array(N * N);
    mem.hitCount = new Uint8Array(N * N);

    for (let gy = 0; gy < N; gy++) {
      for (let gx = 0; gx < N; gx++) {
        if (
          gx === 0 ||
          gy === 0 ||
          gx === N - 1 ||
          gy === N - 1
        ) {
          mem.map[gy * N + gx] = 2;
        }
      }
    }

    mem.mapDirty = true;
    mem.rayFilter = [10, 10, 10, 10, 10];

    mem.headingFiltered = initialHeading;
    mem.headingOffset = 0;
    mem.headingConfidence = 0;
    mem.lastSensorHeading = initialHeading;
    mem.turnRate = 0;

    mem.posHist = [];
    mem.straightTime = 0;
    mem.motorTrim = 0;

    mem.haveCommand = false;
    mem.prevLeft = 0;
    mem.prevRight = 0;

    mem.lastCallT = null;
    mem.lastX = x;
    mem.lastY = y;

    mem.trailX = x;
    mem.trailY = y;

    mem.targetIndex = null;
    mem.seenTargetX = NaN;
    mem.seenTargetY = NaN;

    mem.plan = null;
    mem.lastPlan = -1e9;
    mem.planRetry = -1e9;

    mem.avoid = false;
    mem.avoidSign = 1;
    mem.avoidStart = 0;
    mem.avoidHitX = x;
    mem.avoidHitY = y;
    mem.avoidBest = 1e9;
    mem.avoidCooldown = 0;
    mem.avoidFlips = 0;
    mem.avoidLastFlip = -1e9;
    mem.bias = 1;

    mem.recoverStage = 0;
    mem.recoverSign = 1;
    mem.recoverUntil = 0;

    mem.hardSince = null;

    mem.bestTargetDist = 1e9;
    mem.lastProgressT = now;
    mem.progressSampleT = now;
    mem.progressSampleX = x;
    mem.progressSampleY = y;
    mem.lastMotionT = now;
    mem.motionSampleT = now;
    mem.motionSampleX = x;
    mem.motionSampleY = y;
  }

  let dt = finite(mem.lastCallT) ? now - mem.lastCallT : 0.05;
  if (!finite(dt) || dt <= 0) dt = 0.05;
  dt = clamp(dt, 0.01, 0.15);

  function send(left, right, urgent) {
    if (!finite(left)) left = 0;
    if (!finite(right)) right = 0;

    left = clamp(left, -1, 1);
    right = clamp(right, -1, 1);

    if (mem.haveCommand) {
      const step = urgent ? 0.32 : 0.10;
      left = mem.prevLeft + clamp(left - mem.prevLeft, -step, step);
      right = mem.prevRight + clamp(right - mem.prevRight, -step, step);
    }

    left = clamp(left, -1, 1);
    right = clamp(right, -1, 1);

    mem.prevLeft = left;
    mem.prevRight = right;
    mem.haveCommand = true;
    mem.lastCallT = now;
    mem.lastX = x;
    mem.lastY = y;

    return { left: left, right: right };
  }

  const sensorHeading = finite(obs.heading)
    ? wrap(obs.heading)
    : (finite(mem.lastSensorHeading) ? mem.lastSensorHeading : 0);

  const oldFiltered = finite(mem.headingFiltered)
    ? mem.headingFiltered
    : sensorHeading;

  mem.headingFiltered = wrap(
    oldFiltered + 0.38 * wrap(sensorHeading - oldFiltered)
  );

  const measuredRate =
    wrap(mem.headingFiltered - oldFiltered) / dt;

  if (!finite(mem.turnRate)) mem.turnRate = 0;
  mem.turnRate =
    0.72 * mem.turnRate + 0.28 * measuredRate;

  mem.lastSensorHeading = sensorHeading;

  if (!Array.isArray(mem.posHist)) mem.posHist = [];
  mem.posHist.push({ x: x, y: y, t: now });

  while (
    mem.posHist.length > 1 &&
    now - mem.posHist[0].t > 1.6
  ) {
    mem.posHist.shift();
  }

  const straightCommand =
    mem.haveCommand &&
    mem.prevLeft > 0.25 &&
    mem.prevRight > 0.25 &&
    Math.abs(mem.prevRight - mem.prevLeft) < 0.10 &&
    speed > 0.45;

  if (straightCommand) {
    mem.straightTime += dt;
  } else {
    mem.straightTime = Math.max(
      0,
      mem.straightTime - 2 * dt
    );
  }

  if (
    straightCommand &&
    mem.straightTime > 0.55 &&
    mem.posHist.length > 1
  ) {
    let old = null;

    for (let i = 0; i < mem.posHist.length; i++) {
      if (now - mem.posHist[i].t >= 0.65) {
        old = mem.posHist[i];
        break;
      }
    }

    if (old) {
      const dx = x - old.x;
      const dy = y - old.y;
      const moved = Math.hypot(dx, dy);

      if (
        moved > 0.30 &&
        Math.abs(mem.turnRate) < 60
      ) {
        const course =
          Math.atan2(dy, dx) * 180 / Math.PI;
        const candidate =
          wrap(course - mem.headingFiltered);

        if (Math.abs(candidate) < 105) {
          const gain =
            mem.headingConfidence < 0.25
              ? 0.035
              : 0.012;

          mem.headingOffset = clamp(
            wrap(
              mem.headingOffset +
              gain * wrap(candidate - mem.headingOffset)
            ),
            -90,
            90
          );

          mem.headingConfidence = Math.min(
            1,
            mem.headingConfidence + 0.018
          );
        }
      }
    }
  }

  if (
    straightCommand &&
    mem.straightTime > 1.0 &&
    Math.abs(mem.turnRate) < 70
  ) {
    mem.motorTrim = clamp(
      mem.motorTrim + mem.turnRate * 0.000012,
      -0.06,
      0.06
    );
  }

  if (!finite(mem.headingOffset)) mem.headingOffset = 0;

  const heading = wrap(
    mem.headingFiltered + mem.headingOffset
  );

  const rawRays = new Array(5);
  const sensed = new Array(5);

  if (
    !Array.isArray(mem.rayFilter) ||
    mem.rayFilter.length < 5
  ) {
    mem.rayFilter = [10, 10, 10, 10, 10];
  }

  const rayAngles = [-60, -30, 0, 30, 60];
  const rays = obs.rays;

  for (let i = 0; i < 5; i++) {
    let value;

    if (rays && finite(rays[i])) {
      value = rays[i];
    } else if (
      i === 2 &&
      finite(obs.distanceAhead)
    ) {
      value = obs.distanceAhead;
    } else {
      value = 10;
    }

    value = clamp(value, 0.05, 10);
    rawRays[i] = value;

    let old = finite(mem.rayFilter[i])
      ? mem.rayFilter[i]
      : 10;

    let filtered;

    if (value < old - 0.25) {
      filtered = old + 0.62 * (value - old);
    } else {
      filtered = old + 0.18 * (value - old);
    }

    mem.rayFilter[i] = clamp(filtered, 0.05, 10);

    sensed[i] = clamp(
      Math.min(value, mem.rayFilter[i] + 0.24),
      0.05,
      10
    );
  }

  function cellX(wx) {
    return clamp(
      Math.floor(wx / CELL),
      0,
      N - 1
    );
  }

  function cellY(wy) {
    return clamp(
      Math.floor(wy / CELL),
      0,
      N - 1
    );
  }

  function setFree(gx, gy) {
    if (
      gx < 0 ||
      gy < 0 ||
      gx >= N ||
      gy >= N
    ) {
      return;
    }

    const k = gy * N + gx;

    if (mem.map[k] === 0) {
      mem.map[k] = 1;
    }
  }

  function markHit(gx, gy) {
    if (
      gx < 0 ||
      gy < 0 ||
      gx >= N ||
      gy >= N
    ) {
      return;
    }

    const k = gy * N + gx;

    if (mem.hitCount[k] < 12) {
      mem.hitCount[k]++;
    }

    if (
      mem.hitCount[k] >= 2 &&
      mem.map[k] !== 2
    ) {
      mem.map[k] = 2;
      mem.mapDirty = true;
    }
  }

  if (
    finite(mem.trailX) &&
    finite(mem.trailY)
  ) {
    const dx = x - mem.trailX;
    const dy = y - mem.trailY;
    const distance = Math.hypot(dx, dy);

    if (distance < 3.0) {
      const steps = Math.max(
        1,
        Math.ceil(distance / 0.20)
      );

      for (let j = 0; j <= steps; j++) {
        const q = j / steps;

        setFree(
          cellX(mem.trailX + dx * q),
          cellY(mem.trailY + dy * q)
        );
      }
    }
  }

  setFree(cellX(x), cellY(y));
  mem.trailX = x;
  mem.trailY = y;

  for (let i = 0; i < 5; i++) {
    const a = rad(heading + rayAngles[i]);
    const ca = Math.cos(a);
    const sa = Math.sin(a);

    const raw = rawRays[i];
    const hit = raw < 9.65;

    const freeTo = hit
      ? Math.max(0.05, raw - 0.68)
      : 9.0;

    for (
      let d = 0.18;
      d <= freeTo;
      d += 0.25
    ) {
      setFree(
        cellX(x + ca * d),
        cellY(y + sa * d)
      );
    }

    if (hit) {
      const obstacleDistance = Math.max(
        0.12,
        raw - 0.25
      );

      markHit(
        cellX(x + ca * obstacleDistance),
        cellY(y + sa * obstacleDistance)
      );
    }
  }

  let targetIndex = finite(obs.targetIndex)
    ? Math.max(0, Math.floor(obs.targetIndex))
    : (
      mem.targetIndex === null
        ? 0
        : mem.targetIndex
    );

  let targetX = finite(obs.targetX)
    ? obs.targetX
    : NaN;

  let targetY = finite(obs.targetY)
    ? obs.targetY
    : NaN;

  const targetList = obs.targets;
  const entry =
    targetList &&
    targetList[targetIndex] !== undefined
      ? targetList[targetIndex]
      : null;

  if (entry !== null && entry !== undefined) {
    if (Array.isArray(entry)) {
      if (!finite(targetX) && finite(entry[0])) {
        targetX = entry[0];
      }

      if (!finite(targetY) && finite(entry[1])) {
        targetY = entry[1];
      }
    } else {
      if (!finite(targetX) && finite(entry.x)) {
        targetX = entry.x;
      }

      if (!finite(targetY) && finite(entry.y)) {
        targetY = entry.y;
      }

      if (!finite(targetX) && finite(entry[0])) {
        targetX = entry[0];
      }

      if (!finite(targetY) && finite(entry[1])) {
        targetY = entry[1];
      }
    }
  }

  if (
    (!finite(targetX) || !finite(targetY)) &&
    finite(obs.goalX) &&
    finite(obs.goalY)
  ) {
    targetX = obs.goalX;
    targetY = obs.goalY;
  }

  if (!finite(targetX) || !finite(targetY)) {
    return send(0, 0, true);
  }

  const targetDistance = Math.hypot(
    targetX - x,
    targetY - y
  );

  const targetChanged =
    mem.targetIndex === null ||
    mem.targetIndex !== targetIndex ||
    !finite(mem.seenTargetX) ||
    !finite(mem.seenTargetY) ||
    Math.hypot(
      targetX - mem.seenTargetX,
      targetY - mem.seenTargetY
    ) > 1.0;

  if (targetChanged) {
    mem.targetIndex = targetIndex;
    mem.seenTargetX = targetX;
    mem.seenTargetY = targetY;

    mem.plan = null;
    mem.lastPlan = -1e9;
    mem.planRetry = -1e9;

    mem.avoid = false;
    mem.avoidCooldown = 0;
    mem.avoidFlips = 0;
    mem.recoverStage = 0;
    mem.hardSince = null;

    mem.bias = mem.bias >= 0 ? -1 : 1;

    mem.bestTargetDist = targetDistance;
    mem.lastProgressT = now;
    mem.progressSampleT = now;
    mem.progressSampleX = x;
    mem.progressSampleY = y;
    mem.lastMotionT = now;
    mem.motionSampleT = now;
    mem.motionSampleX = x;
    mem.motionSampleY = y;
  }

  function makePlan(goalWorldX, goalWorldY) {
    const total = N * N;

    const startGX = clamp(
      cellX(x),
      2,
      N - 3
    );

    const startGY = clamp(
      cellY(y),
      2,
      N - 3
    );

    const goalGX = clamp(
      cellX(goalWorldX),
      2,
      N - 3
    );

    const goalGY = clamp(
      cellY(goalWorldY),
      2,
      N - 3
    );

    const start = startGY * N + startGX;
    const goal = goalGY * N + goalGX;

    const gScore = new Float32Array(total);
    gScore.fill(1e20);

    const parent = new Int32Array(total);
    parent.fill(-1);

    const closed = new Uint8Array(total);
    const heapIds = [];
    const heapF = [];

    function heapPush(id, f) {
      let i = heapIds.length;

      heapIds.push(id);
      heapF.push(f);

      while (i > 0) {
        const p = (i - 1) >> 1;

        if (heapF[p] <= f) break;

        heapIds[i] = heapIds[p];
        heapF[i] = heapF[p];
        i = p;
      }

      heapIds[i] = id;
      heapF[i] = f;
    }

    function heapPop() {
      if (heapIds.length === 0) return -1;

      const result = heapIds[0];
      const lastId = heapIds.pop();
      const lastF = heapF.pop();

      if (heapIds.length > 0) {
        let i = 0;

        while (true) {
          const left = i * 2 + 1;

          if (left >= heapIds.length) break;

          const right = left + 1;
          let child = left;

          if (
            right < heapIds.length &&
            heapF[right] < heapF[left]
          ) {
            child = right;
          }

          if (heapF[child] >= lastF) break;

          heapIds[i] = heapIds[child];
          heapF[i] = heapF[child];
          i = child;
        }

        heapIds[i] = lastId;
        heapF[i] = lastF;
      }

      return result;
    }

    function heuristic(id) {
      const gx = id % N;
      const gy = Math.floor(id / N);
      const dx = goalGX - gx;
      const dy = goalGY - gy;

      return Math.sqrt(dx * dx + dy * dy);
    }

    function blockedForPlan(gx, gy, allow) {
      if (
        gx < 0 ||
        gy < 0 ||
        gx >= N ||
        gy >= N
      ) {
        return true;
      }

      const k = gy * N + gx;

      if (k === allow) return false;
      if (mem.map[k] === 2) return true;

      for (let oy = -1; oy <= 1; oy++) {
        for (let ox = -1; ox <= 1; ox++) {
          if (ox === 0 && oy === 0) continue;

          const nx = gx + ox;
          const ny = gy + oy;

          if (
            nx < 0 ||
            ny < 0 ||
            nx >= N ||
            ny >= N
          ) {
            return true;
          }

          if (mem.map[ny * N + nx] === 2) {
            return true;
          }
        }
      }

      return false;
    }

    const dxs = [-1, 0, 1, -1, 1, -1, 0, 1];
    const dys = [-1, -1, -1, 0, 0, 1, 1, 1];

    gScore[start] = 0;
    heapPush(start, heuristic(start));

    let found = false;
    let iterations = 0;

    while (
      heapIds.length > 0 &&
      iterations++ < 6500
    ) {
      const current = heapPop();

      if (current < 0 || closed[current]) {
        continue;
      }

      closed[current] = 1;

      if (current === goal) {
        found = true;
        break;
      }

      const cx = current % N;
      const cy = Math.floor(current / N);

      for (let di = 0; di < 8; di++) {
        const dx = dxs[di];
        const dy = dys[di];
        const nx = cx + dx;
        const ny = cy + dy;

        if (
          nx < 0 ||
          ny < 0 ||
          nx >= N ||
          ny >= N
        ) {
          continue;
        }

        const next = ny * N + nx;

        if (
          next !== goal &&
          blockedForPlan(nx, ny, -1)
        ) {
          continue;
        }

        if (dx !== 0 && dy !== 0) {
          if (
            blockedForPlan(cx + dx, cy, -1) ||
            blockedForPlan(cx, cy + dy, -1)
          ) {
            continue;
          }
        }

        const diagonal = dx !== 0 && dy !== 0;
        const stepCost = diagonal ? 1.41421356 : 1;
        const terrainCost =
          mem.map[next] === 0 ? 1.10 : 1;

        const tentative =
          gScore[current] +
          stepCost * terrainCost;

        if (tentative < gScore[next]) {
          gScore[next] = tentative;
          parent[next] = current;

          heapPush(
            next,
            tentative + heuristic(next)
          );
        }
      }
    }

    if (!found) return null;

    const reversePath = [];
    let q = goal;

    for (let i = 0; i <= total; i++) {
      reversePath.push(q);

      if (q === start) break;

      q = parent[q];

      if (q < 0) return null;
    }

    if (
      reversePath.length === 0 ||
      reversePath[reversePath.length - 1] !== start
    ) {
      return null;
    }

    reversePath.reverse();

    let look = Math.min(
      reversePath.length - 1,
      reversePath.length > 20 ? 6 : 4
    );

    if (look < 1) look = 1;

    const waypointCell = reversePath[look];
    const waypointGX = waypointCell % N;
    const waypointGY = Math.floor(waypointCell / N);

    return {
      x: (waypointGX + 0.5) * CELL,
      y: (waypointGY + 0.5) * CELL,
      goalX: goalWorldX,
      goalY: goalWorldY
    };
  }

  if (targetDistance > 1.35) {
    let needPlan = false;

    if (!mem.plan) {
      if (now >= mem.planRetry) {
        needPlan = true;
      }
    } else if (
      Math.hypot(
        x - mem.plan.x,
        y - mem.plan.y
      ) < 0.65
    ) {
      needPlan = true;
    } else if (
      Math.hypot(
        targetX - mem.plan.goalX,
        targetY - mem.plan.goalY
      ) > 1.0
    ) {
      needPlan = true;
    } else if (
      mem.mapDirty &&
      now - mem.lastPlan > 0.65
    ) {
      needPlan = true;
    }

    if (needPlan) {
      mem.plan = makePlan(targetX, targetY);
      mem.lastPlan = now;
      mem.planRetry = now + 0.70;
      mem.mapDirty = false;
    }
  } else {
    mem.plan = null;
  }

  let navX = targetX;
  let navY = targetY;

  if (mem.plan && targetDistance > 1.35) {
    const waypointDistance = Math.hypot(
      mem.plan.x - x,
      mem.plan.y - y
    );

    if (waypointDistance > 0.58) {
      navX = mem.plan.x;
      navY = mem.plan.y;
    }
  }

  const navAbsolute =
    Math.atan2(navY - y, navX - x) * 180 / Math.PI;

  const navAngle = wrap(
    navAbsolute - heading
  );

  const dampedAngle =
    navAngle -
    0.13 * clamp(mem.turnRate, -180, 180);

  const targetTurn = clamp(
    dampedAngle / 135,
    -1,
    1
  );

  if (
    targetDistance <
    mem.bestTargetDist - 0.08
  ) {
    mem.bestTargetDist = targetDistance;
    mem.lastProgressT = now;
  }

  if (
    now - mem.progressSampleT > 0.90
  ) {
    const moved = Math.hypot(
      x - mem.progressSampleX,
      y - mem.progressSampleY
    );

    if (moved > 0.30) {
      mem.lastMotionT = now;
    }

    mem.progressSampleT = now;
    mem.progressSampleX = x;
    mem.progressSampleY = y;
  }

  if (
    now - mem.motionSampleT > 0.95
  ) {
    const moved = Math.hypot(
      x - mem.motionSampleX,
      y - mem.motionSampleY
    );

    if (moved > 0.30) {
      mem.lastMotionT = now;
    }

    mem.motionSampleT = now;
    mem.motionSampleX = x;
    mem.motionSampleY = y;
  }

  function danger(value, limit) {
    return clamp(
      (limit - value) / limit,
      0,
      1
    );
  }

  const rightRisk = clamp(
    0.55 * danger(sensed[0], 1.5) +
    0.95 * danger(sensed[1], 2.25),
    0,
    1.5
  );

  const leftRisk = clamp(
    0.55 * danger(sensed[4], 1.5) +
    0.95 * danger(sensed[3], 2.25),
    0,
    1.5
  );

  const clearRight =
    0.62 * sensed[1] +
    0.38 * sensed[0];

  const clearLeft =
    0.62 * sensed[3] +
    0.38 * sensed[4];

  const sideTurn = clamp(
    0.52 * (rightRisk - leftRisk),
    -0.8,
    0.8
  );

  const front = Math.min(
    sensed[2],
    sensed[1] + 0.28,
    sensed[3] + 0.28
  );

  const triggerDistance = clamp(
    2.35 + 0.22 * speedAbs,
    2.35,
    2.90
  );

  const frontBlocked =
    front < triggerDistance &&
    (
      Math.abs(navAngle) < 145 ||
      front < 1.0
    );

  if (front < 0.68) {
    if (
      mem.hardSince === null ||
      !finite(mem.hardSince)
    ) {
      mem.hardSince = now;
    }
  } else if (front > 1.02) {
    mem.hardSince = null;
  }

  function enterAvoid() {
    let leftScore = clearLeft;
    let rightScore = clearRight;

    const targetSide = clamp(
      navAngle / 100,
      -1,
      1
    );

    if (targetSide > 0) {
      leftScore += 1.20 * targetSide;
    } else if (targetSide < 0) {
      rightScore += 1.20 * -targetSide;
    }

    let sign;

    if (Math.abs(leftScore - rightScore) < 0.25) {
      sign = mem.bias >= 0 ? 1 : -1;
    } else {
      sign = leftScore > rightScore ? 1 : -1;
    }

    mem.bias = mem.bias >= 0 ? -1 : 1;

    mem.avoid = true;
    mem.avoidSign = sign;
    mem.avoidStart = now;
    mem.avoidHitX = x;
    mem.avoidHitY = y;
    mem.avoidBest = targetDistance;
    mem.avoidFlips = 0;
    mem.avoidLastFlip = -1e9;
  }

  function recoveryOutput() {
    const sign =
      mem.recoverSign >= 0 ? 1 : -1;

    let drive;
    let turnNorm;
    let turnPower;

    if (mem.recoverStage === 1) {
      drive = -0.18;
      turnNorm = 0.60 * sign;
      turnPower = 0.30;
    } else {
      drive = 0;
      turnNorm = sign;
      turnPower = 0.32;
    }

    return send(
      drive - turnPower * turnNorm,
      drive + turnPower * turnNorm,
      true
    );
  }

  if (mem.recoverStage) {
    if (now >= mem.recoverUntil) {
      if (mem.recoverStage === 1) {
        mem.recoverStage = 2;
        mem.recoverUntil = now + 0.72;
      } else {
        mem.recoverStage = 0;
        mem.avoid = true;
        mem.avoidSign = mem.recoverSign;
        mem.avoidStart = now;
        mem.avoidHitX = x;
        mem.avoidHitY = y;
        mem.avoidBest = targetDistance;
        mem.avoidFlips = 0;
        mem.avoidLastFlip = -1e9;
        mem.avoidCooldown = 0;
        mem.plan = null;
        mem.mapDirty = true;
        mem.lastProgressT = now;
        mem.lastMotionT = now;
        mem.hardSince = null;
      }
    }

    if (mem.recoverStage) {
      return recoveryOutput();
    }
  }

  if (mem.avoid) {
    const age = now - mem.avoidStart;
    const chosenClear =
      mem.avoidSign > 0
        ? clearLeft
        : clearRight;

    const chosenInner =
      mem.avoidSign > 0
        ? sensed[3]
        : sensed[1];

    const sideOkay =
      chosenInner > 0.65 ||
      chosenClear > 1.0;

    if (
      age > 0.85 &&
      front > 2.75 &&
      Math.abs(navAngle) < 110 &&
      (sideOkay || age > 2.8)
    ) {
      mem.avoid = false;
      mem.avoidCooldown = now + 0.55;
    }
  }

  if (
    !mem.avoid &&
    now >= mem.avoidCooldown &&
    frontBlocked &&
    (
      targetDistance > 1.05 ||
      front < 0.90
    )
  ) {
    enterAvoid();
  }

  if (mem.avoid) {
    const age = now - mem.avoidStart;
    const chosenInner =
      mem.avoidSign > 0
        ? sensed[3]
        : sensed[1];

    const otherInner =
      mem.avoidSign > 0
        ? sensed[1]
        : sensed[3];

    if (
      age > 0.65 &&
      mem.avoidFlips < 1 &&
      front < 1.35 &&
      chosenInner < 0.55 &&
      otherInner > chosenInner + 0.80
    ) {
      mem.avoidSign = -mem.avoidSign;
      mem.avoidFlips++;
      mem.avoidLastFlip = now;
    }
  }

  let requestRecovery = false;

  if (
    mem.avoid &&
    targetDistance > 1.25
  ) {
    const age = now - mem.avoidStart;
    const loopDistance = Math.hypot(
