    mem.recoverStage = 1;
    mem.recoverStart = now;
    mem.recoverBaseHeading = heading;
    mem.recoverUntil = now + 0.42;

    mem.lastRecoveryT = now;
    mem.lastRecoveryX = x;
    mem.lastRecoveryY = y;
    mem.lastRecoverySign = sign;

