    mem.avoid = false;
    mem.avoidCooldown = now + 0.6;
    mem.plan = null;
    mem.mapDirty = true;
    mem.hardSince = null;
    mem.lastGoalImprove = now;
    mem.bestTargetDist = targetDistance + 0.10;

