    drive *= clamp(
      (targetDistance - 0.43) / 2.57,
      0.15,
      1
    );
  }

  if (targetDistance < 0.72) {
    drive = Math.min(
      drive,
      0.055
    );
  }

  if (
    speedAbs > 1.80 &&
    front < 2.55
  ) {
    drive = Math.min(
      drive,
      0.20
    );
  } else if (
    speedAbs > 1.25 &&
    front < 1.65
  ) {
    drive = Math.min(
      drive,
      0.13
    );
  }

  if (
    sensed[1] < 0.40 ||
    sensed[3] < 0.40
  ) {
    drive = Math.min(
      drive,
      0.05
    );
  }

  if (front < 0.68) {
    drive = 0;
  }

  let turnPower =
    mem.avoid ? 0.35 : 0.32;

  if (angleMagnitude > 118) {
    turnPower = Math.max(
      turnPower,
      0.37
    );
  }

  if (front < 1.12) {
    turnPower = Math.max(
      turnPower,
      0.38
    );
  }

