    mem.lastRawX = rawX;
    mem.lastRawY = rawY;
    mem.lastX = x;
    mem.lastY = y;

    return {
      left: left,
      right: right
    };
  }

  const sensorHeading = finite(obs.heading)
    ? wrap(obs.heading)
    : (finite(mem.lastSensorHeading)
      ? mem.lastSensorHeading
      : 0);

  const oldFiltered = finite(mem.headingFiltered)
    ? mem.headingFiltered
    : sensorHeading;

  mem.headingFiltered = wrap(
    oldFiltered +
    0.40 * wrap(sensorHeading - oldFiltered)
  );

  const measuredRate =
    wrap(mem.headingFiltered - oldFiltered) / dt;

  if (!finite(mem.turnRate)) mem.turnRate = 0;

  mem.turnRate =
    0.76 * mem.turnRate +
    0.24 * measuredRate;

  mem.lastSensorHeading = sensorHeading;

  if (!Array.isArray(mem.posHist)) mem.posHist = [];

  mem.posHist.push({
    x: x,
    y: y,
    t: now
  });

  while (
    mem.posHist.length > 1 &&
    now - mem.posHist[0].t > 7.0
  ) {
    mem.posHist.shift();
  }

  const straightCommand =
    mem.haveCommand &&
    mem.prevLeft > 0.30 &&
    mem.prevRight > 0.30 &&
    Math.abs(mem.prevRight - mem.prevLeft) < 0.11 &&
    speed > 0.55;

  if (straightCommand) {
    mem.straightTime += dt;
  } else {
    mem.straightTime = Math.max(
      0,
      mem.straightTime - 2.0 * dt
    );
  }

  if (
    straightCommand &&
    mem.straightTime > 0.65 &&
    Math.abs(mem.turnRate) < 52 &&
    mem.posHist.length > 2
  ) {
    let old = null;

    for (let i = mem.posHist.length - 1; i >= 0; i--) {
      if (now - mem.posHist[i].t >= 0.70) {
        old = mem.posHist[i];
        break;
      }
    }

    if (old) {
      const dx = x - old.x;
      const dy = y - old.y;
      const moved = Math.hypot(dx, dy);

      if (moved > 0.38) {
        const course =
          Math.atan2(dy, dx) * 180 / Math.PI;

        const candidate =
          wrap(course - mem.headingFiltered);

        if (Math.abs(candidate) < 80) {
          const gain =
            mem.headingConfidence < 0.25
              ? 0.026
              : 0.010;

          mem.headingOffset = clamp(
            wrap(
              mem.headingOffset +
              gain * wrap(candidate - mem.headingOffset)
            ),
            -60,
            60
          );

          mem.headingConfidence = Math.min(
            1,
            mem.headingConfidence + 0.014
          );
        }
      }
    }
  }

  if (!finite(mem.headingOffset)) {
    mem.headingOffset = 0;
  }

  const heading = wrap(
    mem.headingFiltered + mem.headingOffset
  );

  const rawRays = new Array(5);
  const sensed = new Array(5);
  const rayAngles = [-60, -30, 0, 30, 60];

  if (
    !Array.isArray(mem.rayFilter) ||
    mem.rayFilter.length < 5
  ) {
    mem.rayFilter = [10, 10, 10, 10, 10];
  }

  const rays = obs.rays;

  for (let i = 0; i < 5; i++) {
    let value;

    if (rays && finite(rays[i])) {
      value = rays[i];
    } else if (
      i === 2 &&
      finite(obs.distanceAhead)
    ) {
      value = obs.distanceAhead;
    } else {
      value = 10;
    }

    value = clamp(value, 0.05, 10);
    rawRays[i] = value;

    const old = finite(mem.rayFilter[i])
      ? mem.rayFilter[i]
      : 10;

    const gain =
      value < old - 0.22
        ? 0.64
        : 0.16;

    const filtered =
      old + gain * (value - old);

    mem.rayFilter[i] = clamp(
      filtered,
      0.05,
      10
    );

    sensed[i] = clamp(
      Math.min(value, mem.rayFilter[i] + 0.30),
      0.05,
      10
    );
  }

  function cellX(wx) {
    return clamp(
      Math.floor(wx / CELL),
      0,
      N - 1
    );
  }

  function cellY(wy) {
    return clamp(
      Math.floor(wy / CELL),
      0,
      N - 1
    );
  }

  function setFree(gx, gy) {
    if (
      gx < 0 ||
      gy < 0 ||
      gx >= N ||
      gy >= N
    ) {
      return;
    }

    const k = gy * N + gx;

    if (mem.map[k] === 0) {
      mem.map[k] = 1;
    }
  }

  function markHit(gx, gy, distance) {
    if (
      gx < 0 ||
      gy < 0 ||
      gx >= N ||
      gy >= N
    ) {
      return;
    }

    const k = gy * N + gx;

    if (mem.hitCount[k] < 15) {
      mem.hitCount[k]++;
    }

    const required =
      distance < 1.45
        ? 1
        : (distance < 3.5 ? 2 : 3);

    if (
      mem.hitCount[k] >= required &&
      mem.map[k] !== 2
    ) {
      mem.map[k] = 2;
      mem.mapDirty = true;
    }
  }

  if (
    finite(mem.trailX) &&
    finite(mem.trailY)
  ) {
    const dx = x - mem.trailX;
    const dy = y - mem.trailY;
    const distance = Math.hypot(dx, dy);

    if (distance < 3.6) {
      const steps = Math.max(
        1,
        Math.ceil(distance / 0.22)
      );

      for (let j = 0; j <= steps; j++) {
        const q = j / steps;

        setFree(
          cellX(mem.trailX + dx * q),
          cellY(mem.trailY + dy * q)
        );
      }
    }
  }

  setFree(cellX(x), cellY(y));
  mem.trailX = x;
  mem.trailY = y;

  for (let i = 0; i < 5; i++) {
    const a = rad(heading + rayAngles[i]);
    const ca = Math.cos(a);
    const sa = Math.sin(a);

    const raw = rawRays[i];
    const hit = raw < 9.5;

    const freeTo = hit
      ? Math.max(0.08, raw - 0.62)
      : 8.6;

    for (
      let d = 0.18;
      d <= freeTo;
      d += 0.25
    ) {
      setFree(
        cellX(x + ca * d),
        cellY(y + sa * d)
      );
    }

    if (hit) {
      const obstacleDistance = Math.max(
        0.12,
        raw - 0.28
      );

      markHit(
        cellX(x + ca * obstacleDistance),
        cellY(y + sa * obstacleDistance),
        raw
      );
    }
  }

  const currentCell =
    cellY(y) * N + cellX(x);

  if (
    mem.visitCell !== currentCell ||
    now - mem.visitT > 0.34
  ) {
    mem.visit[currentCell] = Math.min(
      255,
      mem.visit[currentCell] + 1
    );

    mem.visitCell = currentCell;
    mem.visitT = now;
  }

  let targetIndex = finite(obs.targetIndex)
    ? Math.max(0, Math.floor(obs.targetIndex))
    : (
      mem.targetIndex === null ||
      !finite(mem.targetIndex)
        ? 0
        : mem.targetIndex
    );

  let targetX = finite(obs.targetX)
    ? obs.targetX
    : NaN;

  let targetY = finite(obs.targetY)
    ? obs.targetY
    : NaN;

  const targetList = obs.targets;

  const entry =
    targetList &&
    targetList[targetIndex] !== undefined
      ? targetList[targetIndex]
      : null;

  if (entry !== null && entry !== undefined) {
    if (Array.isArray(entry)) {
      if (!finite(targetX) && finite(entry[0])) {
        targetX = entry[0];
      }

      if (!finite(targetY) && finite(entry[1])) {
        targetY = entry[1];
      }
    } else {
      if (!finite(targetX) && finite(entry.x)) {
        targetX = entry.x;
      }

      if (!finite(targetY) && finite(entry.y)) {
        targetY = entry.y;
      }

      if (!finite(targetX) && finite(entry[0])) {
        targetX = entry[0];
      }

      if (!finite(targetY) && finite(entry[1])) {
        targetY = entry[1];
      }
    }
  }

  if (
    (!finite(targetX) || !finite(targetY)) &&
    finite(obs.goalX) &&
    finite(obs.goalY)
  ) {
    targetX = obs.goalX;
    targetY = obs.goalY;
  }

  if (!finite(targetX) || !finite(targetY)) {
    return send(0, 0, true);
  }

  const targetDistance = Math.hypot(
    targetX - x,
    targetY - y
  );

  const targetChanged =
    mem.targetIndex === null ||
    mem.targetIndex !== targetIndex ||
    !finite(mem.seenTargetX) ||
    !finite(mem.seenTargetY) ||
    Math.hypot(
      targetX - mem.seenTargetX,
      targetY - mem.seenTargetY
    ) > 1.0;

  if (targetChanged) {
    mem.targetIndex = targetIndex;
    mem.seenTargetX = targetX;
    mem.seenTargetY = targetY;

    mem.plan = null;
    mem.lastPlan = -1e9;
    mem.planRetry = -1e9;
    mem.mapDirty = true;

    mem.avoid = false;
    mem.avoidCooldown = 0;
    mem.avoidFlips = 0;
    mem.recoverStage = 0;
    mem.escapeUntil = 0;
    mem.hardSince = null;

    mem.bias = mem.bias >= 0 ? -1 : 1;

    mem.bestTargetDist = targetDistance;
    mem.lastGoalImprove = now;
    mem.lastMotionT = now;
    mem.recoverySuppress = now + 1.0;
  }

  function makePlan(goalWorldX, goalWorldY) {
    const startGX = cellX(x);
    const startGY = cellY(y);
    const goalGX = cellX(goalWorldX);
    const goalGY = cellY(goalWorldY);

    const start = startGY * N + startGX;
    const goal = goalGY * N + goalGX;

    if (start === goal) {
      return null;
    }

    const blocked = new Uint8Array(TOTAL);

    for (let gy = 0; gy < N; gy++) {
      for (let gx = 0; gx < N; gx++) {
        const k = gy * N + gx;

        if (
          gx <= 0 ||
          gy <= 0 ||
          gx >= N - 1 ||
          gy >= N - 1 ||
          mem.map[k] === 2
        ) {
          blocked[k] = 1;
        }
      }
    }

    for (let gy = 0; gy < N; gy++) {
      for (let gx = 0; gx < N; gx++) {
        const k = gy * N + gx;

        if (mem.map[k] !== 2) {
          continue;
        }

        for (let oy = -1; oy <= 1; oy++) {
          for (let ox = -1; ox <= 1; ox++) {
            const nx = gx + ox;
            const ny = gy + oy;

            if (
              nx >= 0 &&
              ny >= 0 &&
              nx < N &&
              ny < N
            ) {
              blocked[ny * N + nx] = 1;
            }
          }
        }
      }
    }

    blocked[start] = 0;
    blocked[goal] = 0;

    const gScore = new Float32Array(TOTAL);
    gScore.fill(1e20);

    const parent = new Int32Array(TOTAL);
    parent.fill(-1);

    const closed = new Uint8Array(TOTAL);
    const heapIds = [];
    const heapF = [];

    function heapPush(id, f) {
      let i = heapIds.length;

      heapIds.push(id);
      heapF.push(f);

      while (i > 0) {
        const p = (i - 1) >> 1;

        if (heapF[p] <= f) {
          break;
        }

        heapIds[i] = heapIds[p];
        heapF[i] = heapF[p];
        i = p;
      }

      heapIds[i] = id;
      heapF[i] = f;
    }

    function heapPop() {
      if (heapIds.length === 0) {
        return -1;
      }

      const result = heapIds[0];
      const lastId = heapIds.pop();
      const lastF = heapF.pop();

      if (heapIds.length > 0) {
        let i = 0;

        while (true) {
          const left = i * 2 + 1;

          if (left >= heapIds.length) {
            break;
          }

          const right = left + 1;
          let child = left;

          if (
            right < heapIds.length &&
            heapF[right] < heapF[left]
          ) {
            child = right;
          }

          if (heapF[child] >= lastF) {
            break;
          }

          heapIds[i] = heapIds[child];
          heapF[i] = heapF[child];
          i = child;
        }

        heapIds[i] = lastId;
        heapF[i] = lastF;
      }

      return result;
    }

    function heuristic(id) {
      const gx = id % N;
      const gy = Math.floor(id / N);
      const dx = goalGX - gx;
      const dy = goalGY - gy;

      return Math.sqrt(dx * dx + dy * dy);
    }

    const dxs = [-1, 0, 1, -1, 1, -1, 0, 1];
    const dys = [-1, -1, -1, 0, 0, 1, 1, 1];

    gScore[start] = 0;
    heapPush(start, heuristic(start));

    let found = false;
    let iterations = 0;

    while (
      heapIds.length > 0 &&
      iterations++ < 2700
    ) {
      const current = heapPop();

      if (current < 0 || closed[current]) {
        continue;
      }

      closed[current] = 1;

      if (current === goal) {
        found = true;
        break;
      }

      const cx = current % N;
      const cy = Math.floor(current / N);

      for (let di = 0; di < 8; di++) {
        const dx = dxs[di];
        const dy = dys[di];
        const nx = cx + dx;
        const ny = cy + dy;

        if (
          nx < 0 ||
          ny < 0 ||
          nx >= N ||
          ny >= N
        ) {
          continue;
        }

        const next = ny * N + nx;

        if (
          blocked[next] &&
          next !== goal &&
          next !== start
        ) {
          continue;
        }

        if (closed[next]) {
          continue;
        }

        if (dx !== 0 && dy !== 0) {
          const sideA = cy * N + nx;
          const sideB = ny * N + cx;

          if (
            (
              blocked[sideA] &&
              sideA !== goal &&
              sideA !== start
            ) ||
            (
              blocked[sideB] &&
              sideB !== goal &&
              sideB !== start
            )
          ) {
            continue;
          }
        }

        const diagonal =
          dx !== 0 && dy !== 0;

        const stepCost =
          diagonal ? 1.41421356 : 1;

        const unknownCost =
          mem.map[next] === 0
            ? 1.07
            : 1.0;

        const visitPenalty =
          1 +
          Math.min(
            0.18,
            (mem.visit[next] || 0) * 0.012
          );

        const tentative =
          gScore[current] +
          stepCost *
          unknownCost *
          visitPenalty;

        if (tentative < gScore[next]) {
          gScore[next] = tentative;
          parent[next] = current;

          heapPush(
            next,
            tentative + heuristic(next)
          );
        }
      }
    }

    if (!found) {
      return null;
    }

    const reversePath = [];
    let q = goal;

    for (let i = 0; i <= TOTAL + 1; i++) {
      reversePath.push(q);

      if (q === start) {
        break;
      }

      q = parent[q];

      if (q < 0) {
        return null;
      }
    }

    if (
      reversePath.length === 0 ||
      reversePath[reversePath.length - 1] !== start
    ) {
      return null;
    }

    reversePath.reverse();

    let look = Math.min(
      reversePath.length - 1,
      reversePath.length > 20 ? 5 : 4
    );

    if (
      look < 1 &&
      reversePath.length > 1
    ) {
      look = 1;
    }

    const waypoint = reversePath[look];
    const waypointGX = waypoint % N;
    const waypointGY = Math.floor(waypoint / N);

    return {
      x: (waypointGX + 0.5) * CELL,
      y: (waypointGY + 0.5) * CELL,
      goalX: goalWorldX,
      goalY: goalWorldY
    };
  }

  if (
    !mem.avoid &&
    targetDistance > 1.5
  ) {
    let needPlan = false;

    if (!mem.plan) {
      if (now >= mem.planRetry) {
        needPlan = true;
      }
    } else {
      const waypointDistance = Math.hypot(
        mem.plan.x - x,
        mem.plan.y - y
      );

      if (
        waypointDistance < 0.64 &&
        now - mem.lastPlan > 0.80
      ) {
        needPlan = true;
      } else if (
        Math.hypot(
          targetX - mem.plan.goalX,
          targetY - mem.plan.goalY
        ) > 0.90
      ) {
        needPlan = true;
      } else if (
        mem.mapDirty &&
        now - mem.lastPlan > 0.95
      ) {
        needPlan = true;
      }
    }

    if (needPlan) {
      mem.plan = makePlan(targetX, targetY);
      mem.lastPlan = now;
      mem.planRetry = now + 0.85;
      mem.mapDirty = false;
    }
  } else if (targetDistance <= 1.5) {
    mem.plan = null;
  }

  let navX = targetX;
  let navY = targetY;

  if (
    mem.plan &&
    !mem.avoid &&
    targetDistance > 1.5
  ) {
    const waypointDistance = Math.hypot(
      mem.plan.x - x,
      mem.plan.y - y
    );

    if (waypointDistance > 0.82) {
      navX = mem.plan.x;
      navY = mem.plan.y;
    }
  }

  const navAbsolute =
    Math.atan2(navY - y, navX - x) *
    180 / Math.PI;

  const goalAbsolute =
    Math.atan2(targetY - y, targetX - x) *
    180 / Math.PI;

  const navAngle = wrap(
    navAbsolute - heading
  );

  const goalAngle = wrap(
    goalAbsolute - heading
  );

  const targetTurn = clamp(
    (
      navAngle -
      0.07 * clamp(mem.turnRate, -220, 220)
    ) / 100,
    -1,
    1
  );

  const goalTurn = clamp(
    (
      goalAngle -
      0.07 * clamp(mem.turnRate, -220, 220)
    ) / 100,
    -1,
    1
  );

  if (
    targetDistance <
    mem.bestTargetDist - 0.08
  ) {
    mem.bestTargetDist = targetDistance;
    mem.lastGoalImprove = now;
  }

  function historyStats(seconds) {
    const h = mem.posHist;

    if (!h || h.length < 2) {
      return {
        net: 0,
        travel: 0
      };
    }

    let first = 0;

    while (
      first < h.length - 1 &&
      now - h[first].t > seconds
    ) {
      first++;
    }

    const dx = x - h[first].x;
    const dy = y - h[first].y;

    let travel = 0;

    for (let i = first + 1; i < h.length; i++) {
      const sx = h[i].x - h[i - 1].x;
      const sy = h[i].y - h[i - 1].y;
      const d = Math.hypot(sx, sy);

      travel += Math.min(d, 0.32);
    }

    return {
      net: Math.hypot(dx, dy),
      travel: travel
    };
  }

  const stats1 = historyStats(1.05);
  const stats3 = historyStats(3.20);
  const stats5 = historyStats(5.40);

  if (stats1.net > 0.30) {
    mem.lastMotionT = now;
  }

  function danger(value, limit) {
    return clamp(
      (limit - value) / limit,
      0,
      1
    );
  }

  const rightRisk = clamp(
    0.56 * danger(sensed[0], 1.35) +
    0.98 * danger(sensed[1], 2.05),
    0,
    1.55
  );

  const leftRisk = clamp(
    0.56 * danger(sensed[4], 1.35) +
    0.98 * danger(sensed[3], 2.05),
    0,
    1.55
  );

  const clearRight =
    0.64 * sensed[1] +
    0.36 * sensed[0];

  const clearLeft =
    0.64 * sensed[3] +
    0.36 * sensed[4];

  const sideRepel = clamp(
    0.54 * (rightRisk - leftRisk),
    -0.82,
    0.82
  );

  let boundaryTurn = 0;

  if (x < 1.15) {
    boundaryTurn -= clamp(
      (1.15 - x) * 0.55,
      0,
      0.55
    );
  }

  if (x > 38.85) {
    boundaryTurn += clamp(
      (x - 38.85) * 0.55,
      0,
      0.55
    );
  }

  if (y < 1.15) {
    boundaryTurn += clamp(
      (1.15 - y) * 0.55,
      0,
      0.55
    );
  }

  if (y > 38.85) {
    boundaryTurn -= clamp(
      (y - 38.85) * 0.55,
      0,
      0.55
    );
  }

  let front = sensed[2];

  if (sensed[1] < 1.85) {
    front = Math.min(
      front,
      sensed[1] + 0.42
    );
  }

  if (sensed[3] < 1.85) {
    front = Math.min(
      front,
      sensed[3] + 0.42
    );
  }

  const triggerDistance = clamp(
    2.15 + 0.17 * speedAbs,
    2.15,
    2.55
  );

  const frontBlocked =
    front < triggerDistance;

  if (
    front < 0.75 &&
    targetDistance > 1.10
  ) {
    if (
      mem.hardSince === null ||
      !finite(mem.hardSince)
    ) {
      mem.hardSince = now;
    }
  } else if (front > 1.10) {
    mem.hardSince = null;
  }

  function enterAvoid() {
    let leftScore = clearLeft;
    let rightScore = clearRight;

    if (goalAngle > 12) {
      leftScore += 0.42;
    } else if (goalAngle < -12) {
      rightScore += 0.42;
    }

    let sign;

    if (Math.abs(leftScore - rightScore) < 0.24) {
      sign = mem.bias >= 0 ? 1 : -1;
    } else {
      sign =
        leftScore > rightScore
          ? 1
          : -1;
    }

    mem.bias = mem.bias >= 0 ? -1 : 1;

    mem.avoid = true;
    mem.avoidSign = sign;
    mem.avoidStart = now;
    mem.avoidHitX = x;
    mem.avoidHitY = y;
    mem.avoidHitDistance = targetDistance;
    mem.avoidBest = targetDistance;
    mem.avoidFlips = 0;
  }

  function recoveryOutput() {
    const sign =
      mem.recoverSign >= 0
        ? 1
        : -1;

    let drive = 0;
    let turnNorm = 0;
    let turnPower = 0;

    if (mem.recoverStage === 1) {
      drive = -0.27;
      turnNorm = 0.16 * sign;
      turnPower = 0.25;
    } else if (mem.recoverStage === 2) {
      drive = 0;
      turnNorm = sign;
      turnPower = 0.44;
    } else {
      drive = 0.38;

      turnNorm = clamp(
        goalTurn +
        0.25 * sign +
        0.22 * sideRepel +
        boundaryTurn,
        -1,
        1
      );

      turnPower = 0.35;

      if (front < 1.15) {
        drive *= clamp(
          (front - 0.55) / 0.60,
          0,
          1
        );
      }

      if (front < 0.62) {
        drive = 0;
      }
    }

    return send(
      drive - turnPower * turnNorm,
      drive + turnPower * turnNorm,
      true
    );
  }

  if (mem.recoverStage) {
    if (
      mem.recoverStage === 1 &&
      now >= mem.recoverUntil
    ) {
      mem.recoverStage = 2;
      mem.recoverUntil = now + 1.70;
    }

    if (mem.recoverStage === 2) {
      const turned = Math.abs(
        wrap(heading - mem.recoverBaseHeading)
      );

      const turnGoal =
        mem.recoverLong
          ? 150
          : 122;

      if (
        (
          turned > turnGoal &&
          now - mem.recoverStart > 0.45
