    (!finite(targetX) || !finite(targetY)) &&
    finite(obs.goalX) &&
    finite(obs.goalY)
  ) {
    targetX = obs.goalX;
    targetY = obs.goalY;
  }

  if (!finite(targetX) || !finite(targetY)) {
    return send(0, 0, true);
  }

  const targetDistance = Math.hypot(
    targetX - x,
    targetY - y
  );

  const targetChanged =
    mem.targetIndex === null ||
    mem.targetIndex !== targetIndex ||
    !finite(mem.seenTargetX) ||
    !finite(mem.seenTargetY) ||
    Math.hypot(
      targetX - mem.seenTargetX,
      targetY - mem.seenTargetY
    ) > 1.0;

  if (targetChanged) {
    mem.targetIndex = targetIndex;
    mem.seenTargetX = targetX;
    mem.seenTargetY = targetY;

    mem.plan = null;
    mem.lastPlan = -1e9;
    mem.planRetry = -1e9;
    mem.mapDirty = true;

    mem.avoid = false;
    mem.avoidCooldown = 0;
    mem.avoidFlips = 0;
    mem.recoverStage = 0;
    mem.escapeUntil = 0;
    mem.hardSince = null;

    mem.bias = mem.bias >= 0 ? -1 : 1;

    mem.bestTargetDist = targetDistance;
    mem.lastGoalImprove = now;
    mem.lastMotionT = now;
    mem.recoverySuppress = now + 1.0;
  }

  function makePlan(goalWorldX, goalWorldY) {
    const startGX = cellX(x);
    const startGY = cellY(y);
    const goalGX = cellX(goalWorldX);
    const goalGY = cellY(goalWorldY);

    const start = startGY * N + startGX;
    const goal = goalGY * N + goalGX;

    if (start === goal) {
      return null;
    }

    const blocked = new Uint8Array(TOTAL);

    for (let gy = 0; gy < N; gy++) {
      for (let gx = 0; gx < N; gx++) {
        const k = gy * N + gx;

        if (
          gx <= 0 ||
          gy <= 0 ||
          gx >= N - 1 ||
          gy >= N - 1 ||
          mem.map[k] === 2
        ) {
          blocked[k] = 1;
        }
      }
    }

    for (let gy = 0; gy < N; gy++) {
      for (let gx = 0; gx < N; gx++) {
        const k = gy * N + gx;

        if (mem.map[k] !== 2) {
          continue;
        }

        for (let oy = -1; oy <= 1; oy++) {
          for (let ox = -1; ox <= 1; ox++) {
            const nx = gx + ox;
            const ny = gy + oy;

            if (
              nx >= 0 &&
              ny >= 0 &&
              nx < N &&
              ny < N
            ) {
              blocked[ny * N + nx] = 1;
            }
          }
        }
      }
    }

    blocked[start] = 0;
    blocked[goal] = 0;

    const gScore = new Float32Array(TOTAL);
    gScore.fill(1e20);

    const parent = new Int32Array(TOTAL);
    parent.fill(-1);

    const closed = new Uint8Array(TOTAL);
    const heapIds = [];
    const heapF = [];

    function heapPush(id, f) {
      let i = heapIds.length;

      heapIds.push(id);
      heapF.push(f);

      while (i > 0) {
        const p = (i - 1) >> 1;

        if (heapF[p] <= f) {
          break;
        }

        heapIds[i] = heapIds[p];
        heapF[i] = heapF[p];
        i = p;
      }

      heapIds[i] = id;
      heapF[i] = f;
    }

    function heapPop() {
      if (heapIds.length === 0) {
        return -1;
      }

      const result = heapIds[0];
      const lastId = heapIds.pop();
      const lastF = heapF.pop();

      if (heapIds.length > 0) {
        let i = 0;

        while (true) {
          const left = i * 2 + 1;

          if (left >= heapIds.length) {
            break;
          }

          const right = left + 1;
          let child = left;

          if (
            right < heapIds.length &&
            heapF[right] < heapF[left]
          ) {
            child = right;
          }

          if (heapF[child] >= lastF) {
            break;
          }

          heapIds[i] = heapIds[child];
          heapF[i] = heapF[child];
          i = child;
        }

        heapIds[i] = lastId;
        heapF[i] = lastF;
      }

      return result;
    }

    function heuristic(id) {
      const gx = id % N;
      const gy = Math.floor(id / N);
      const dx = goalGX - gx;
      const dy = goalGY - gy;

      return Math.sqrt(dx * dx + dy * dy);
    }

    const dxs = [-1, 0, 1, -1, 1, -1, 0, 1];
    const dys = [-1, -1, -1, 0, 0, 1, 1, 1];

    gScore[start] = 0;
    heapPush(start, heuristic(start));

    let found = false;
    let iterations = 0;

    while (
      heapIds.length > 0 &&
      iterations++ < 5200
    ) {
      const current = heapPop();

      if (current < 0 || closed[current]) {
        continue;
      }

      closed[current] = 1;

      if (current === goal) {
        found = true;
        break;
      }

      const cx = current % N;
      const cy = Math.floor(current / N);

      for (let di = 0; di < 8; di++) {
        const dx = dxs[di];
        const dy = dys[di];
        const nx = cx + dx;
        const ny = cy + dy;

        if (
          nx < 0 ||
          ny < 0 ||
          nx >= N ||
          ny >= N
        ) {
          continue;
        }

        const next = ny * N + nx;

        if (
          blocked[next] &&
          next !== goal &&
          next !== start
        ) {
          continue;
        }

        if (closed[next]) {
          continue;
        }

        if (dx !== 0 && dy !== 0) {
          const sideA = cy * N + nx;
          const sideB = ny * N + cx;

          if (
            (
              blocked[sideA] &&
              sideA !== goal &&
              sideA !== start
            ) ||
            (
              blocked[sideB] &&
              sideB !== goal &&
              sideB !== start
            )
          ) {
            continue;
          }
        }

        const diagonal =
          dx !== 0 && dy !== 0;

        const stepCost =
          diagonal ? 1.41421356 : 1;

        const unknownCost =
          mem.map[next] === 0
            ? 1.12
            : 1.0;

        const visitPenalty =
          1 +
          Math.min(
            0.20,
            (mem.visit[next] || 0) * 0.014
          );

        const tentative =
          gScore[current] +
          stepCost *
          unknownCost *
          visitPenalty;

        if (tentative < gScore[next]) {
          gScore[next] = tentative;
          parent[next] = current;

          heapPush(
            next,
            tentative + heuristic(next)
          );
        }
      }
    }

    if (!found) {
      return null;
    }

    const reversePath = [];
    let q = goal;

    for (let i = 0; i <= TOTAL + 1; i++) {
      reversePath.push(q);

      if (q === start) {
        break;
      }

      q = parent[q];

      if (q < 0) {
        return null;
      }
    }

    if (
      reversePath.length === 0 ||
      reversePath[reversePath.length - 1] !== start
    ) {
      return null;
    }

    reversePath.reverse();

    const look = Math.min(
      reversePath.length - 1,
      reversePath.length > 16 ? 4 : 3
    );

    if (look < 1) {
      return null;
    }

    const waypoint = reversePath[look];
    const waypointGX = waypoint % N;
    const waypointGY = Math.floor(waypoint / N);

    return {
      x: (waypointGX + 0.5) * CELL,
      y: (waypointGY + 0.5) * CELL,
      goalX: goalWorldX,
      goalY: goalWorldY
    };
  }

  if (
    !mem.avoid &&
    targetDistance > 1.65
  ) {
    let needPlan = false;

    if (!mem.plan) {
      if (now >= mem.planRetry) {
        needPlan = true;
      }
    } else {
      const waypointDistance = Math.hypot(
        mem.plan.x - x,
        mem.plan.y - y
      );

      if (
        waypointDistance < 0.78 &&
        now - mem.lastPlan > 0.75
      ) {
        needPlan = true;
      } else if (
        Math.hypot(
          targetX - mem.plan.goalX,
          targetY - mem.plan.goalY
        ) > 0.9
      ) {
        needPlan = true;
      } else if (
        mem.mapDirty &&
        now - mem.lastPlan > 0.85
      ) {
        needPlan = true;
      }
    }

    if (needPlan) {
      mem.plan = makePlan(targetX, targetY);
      mem.lastPlan = now;
      mem.planRetry = now + 0.80;
      mem.mapDirty = false;
    }
  } else if (targetDistance <= 1.65) {
    mem.plan = null;
  }

  let navX = targetX;
  let navY = targetY;

  if (
    mem.plan &&
    !mem.avoid &&
    targetDistance > 1.65
  ) {
    const waypointDistance = Math.hypot(
      mem.plan.x - x,
      mem.plan.y - y
    );

    if (waypointDistance > 0.85) {
      navX = mem.plan.x;
      navY = mem.plan.y;
    }
  }

  const navAbsolute =
    Math.atan2(navY - y, navX - x) *
    180 / Math.PI;

  const goalAbsolute =
    Math.atan2(targetY - y, targetX - x) *
    180 / Math.PI;

  const navAngle = wrap(
    navAbsolute - heading
  );

  const goalAngle = wrap(
    goalAbsolute - heading
  );

  const targetTurn = clamp(
    (
      navAngle -
      0.035 * clamp(mem.turnRate, -220, 220)
    ) / 88,
    -1,
    1
  );

  const goalTurn = clamp(
    (
      goalAngle -
      0.035 * clamp(mem.turnRate, -220, 220)
    ) / 88,
    -1,
    1
  );

  if (
    targetDistance <
    mem.bestTargetDist - 0.07
  ) {
    mem.bestTargetDist = targetDistance;
    mem.lastGoalImprove = now;
  }

  function historyStats(seconds) {
    const h = mem.posHist;

    if (!h || h.length < 2) {
      return {
        net: 0,
        travel: 0
      };
    }

    let first = 0;

    while (
      first < h.length - 1 &&
      now - h[first].t > seconds
    ) {
      first++;
    }

    const dx = x - h[first].x;
    const dy = y - h[first].y;

    let travel = 0;

    for (let i = first + 1; i < h.length; i++) {
      const sx = h[i].x - h[i - 1].x;
      const sy = h[i].y - h[i - 1].y;
      const d = Math.hypot(sx, sy);

      travel += Math.min(d, 0.34);
    }

    return {
      net: Math.hypot(dx, dy),
      travel: travel
    };
  }

  const stats1 = historyStats(1.05);
  const stats3 = historyStats(3.25);
  const stats5 = historyStats(5.5);

  if (stats1.net > 0.29) {
    mem.lastMotionT = now;
  }

  function danger(value, limit) {
    return clamp(
      (limit - value) / limit,
      0,
      1
    );
  }

  const rightRisk = clamp(
    0.62 * danger(sensed[0], 1.45) +
    1.00 * danger(sensed[1], 2.10),
    0,
    1.6
  );

  const leftRisk = clamp(
    0.62 * danger(sensed[4], 1.45) +
    1.00 * danger(sensed[3], 2.10),
    0,
    1.6
  );

  const clearRight =
    0.64 * sensed[1] +
    0.36 * sensed[0];

  const clearLeft =
    0.64 * sensed[3] +
    0.36 * sensed[4];

  const sideRepel = clamp(
    0.72 * (rightRisk - leftRisk),
    -1,
    1
  );

  let front = sensed[2];

  if (sensed[1] < 2.30) {
    front = Math.min(
      front,
      sensed[1] + 0.45
    );
  }

  if (sensed[3] < 2.30) {
    front = Math.min(
      front,
      sensed[3] + 0.45
    );
  }

  if (sensed[0] < 0.70) {
    front = Math.min(
      front,
      sensed[0] + 0.65
    );
  }

  if (sensed[4] < 0.70) {
    front = Math.min(
      front,
      sensed[4] + 0.65
    );
  }

  let bx = 0;
  let by = 0;

  if (x < 1.35) bx += 1.35 - x;
  if (x > 38.65) bx -= x - 38.65;
  if (y < 1.35) by += 1.35 - y;
  if (y > 38.65) by -= y - 38.65;

  let boundaryTurn = 0;
  const boundaryMagnitude = Math.hypot(bx, by);

  if (boundaryMagnitude > 0.02) {
    const boundaryAngle =
      Math.atan2(by, bx) * 180 / Math.PI;

    boundaryTurn = clamp(
      wrap(boundaryAngle - heading) / 105 *
      clamp(boundaryMagnitude / 1.35, 0, 1),
      -0.65,
      0.65
    );
  }

  const rightClose = Math.min(
    sensed[0],
    sensed[1]
  );

  const leftClose = Math.min(
    sensed[4],
    sensed[3]
  );

  let emergencyTerm = 0;
  let sideEmergency = false;

  if (
    rightClose < 0.92 &&
    (
      leftClose > 1.05 ||
      rightClose + 0.22 < leftClose
    )
  ) {
    emergencyTerm = clamp(
      (1.02 - rightClose) / 0.58,
      0,
      1
    );
    sideEmergency = true;
  } else if (
    leftClose < 0.92 &&
    (
      rightClose > 1.05 ||
      leftClose + 0.22 < rightClose
    )
  ) {
    emergencyTerm = -clamp(
      (1.02 - leftClose) / 0.58,
      0,
      1
    );
    sideEmergency = true;
  }

  const sideCrowded =
    rightClose < 0.82 &&
    leftClose < 0.82;

  const triggerDistance = clamp(
    2.18 + 0.15 * speedAbs,
    2.18,
    2.52
  );

  const frontBlocked =
    front < triggerDistance;

  if (
    front < 0.76 &&
    targetDistance > 1.08
  ) {
    if (
      mem.hardSince === null ||
      !finite(mem.hardSince)
    ) {
      mem.hardSince = now;
    }
  } else if (front > 1.16) {
    mem.hardSince = null;
  }

  function enterAvoid() {
    let leftScore = clearLeft;
    let rightScore = clearRight;

    if (goalAngle > 15) {
      leftScore += 0.42;
    } else if (goalAngle < -15) {
      rightScore += 0.42;
    }

    let sign;

    if (Math.abs(leftScore - rightScore) < 0.25) {
      sign = mem.bias >= 0 ? 1 : -1;
    } else {
      sign =
        leftScore > rightScore
          ? 1
          : -1;
    }

    mem.bias = mem.bias >= 0 ? -1 : 1;

    mem.avoid = true;
    mem.avoidSign = sign;
    mem.avoidStart = now;
    mem.avoidHitDistance = targetDistance;
    mem.avoidBest = targetDistance;
    mem.avoidFlips = 0;

    mem.plan = null;
    mem.planRetry = now + 0.25;
  }

  if (mem.avoid) {
    const age = now - mem.avoidStart;

    if (
      targetDistance <
      mem.avoidBest - 0.05
    ) {
      mem.avoidBest = targetDistance;
    }

    const wallSide =
      mem.avoidSign > 0
        ? -1
        : 1;

    const wallDistance =
      wallSide < 0
        ? sensed[1]
        : sensed[3];

    let wallTerm = 0;

    if (wallDistance < 3.6) {
      const wallError =
        clamp(
          (1.02 - wallDistance) / 1.05,
          -0.62,
          0.72
        );

      wallTerm = -wallSide * wallError;
    }

    const directClear =
      front > 2.58 &&
      Math.abs(goalAngle) < 76 &&
      (
        wallDistance > 0.52 ||
        (
          wallSide < 0
            ? sensed[0] > 0.85
            : sensed[4] > 0.85
        )
      );

    const improvedEnough =
      targetDistance <
      mem.avoidHitDistance - 0.16;

    const lateLeave =
      age > 6.0 &&
      targetDistance <
      mem.avoidHitDistance + 0.12;

    if (
      targetDistance < 1.02 ||
      (
        age > 0.95 &&
        directClear &&
        (
          improvedEnough ||
          lateLeave
        )
      ) ||
      (
        age > 8.0 &&
        front > 3.0 &&
        Math.abs(goalAngle) < 105 &&
        targetDistance <
        mem.avoidHitDistance + 0.28
      )
    ) {
      mem.avoid = false;
      mem.avoidCooldown = now + 0.72;
      mem.plan = null;
      mem.planRetry = now + 0.25;
    }

    if (
      mem.avoid &&
      age > 1.0 &&
      mem.avoidFlips < 1 &&
      front < 1.48
    ) {
      const selectedInner =
        mem.avoidSign > 0
          ? sensed[1]
          : sensed[3];

      const otherInner =
        mem.avoidSign > 0
          ? sensed[3]
          : sensed[1];

      if (
        selectedInner < 0.55 &&
        otherInner > selectedInner + 0.72
      ) {
        mem.avoidSign = -mem.avoidSign;
        mem.avoidFlips++;
      }
    }
  }

  if (
    !mem.avoid &&
    now >= mem.avoidCooldown &&
    frontBlocked &&
    (
      targetDistance > 1.02 ||
      front < 0.70
    )
  ) {
    enterAvoid();
  }

  const noGoalProgress =
    now - mem.lastGoalImprove > 5.1;

  const loop3 =
    stats3.net < 1.25 &&
    stats3.travel > 1.45;

  const loop5 =
    stats5.net < 2.0 &&
    stats5.travel > 2.7;

  const repeatedCell =
    mem.visit[currentCell] > 9 &&
    stats3.travel > 1.25;

  const stationary =
    stats1.net < 0.28 &&
    speedAbs < 0.42 &&
    noGoalProgress &&
    (
      front < 1.9 ||
      Math.abs(goalAngle) > 108
    );

  let requestRecovery = false;

  if (
    targetDistance > 1.20 &&
    now >= mem.recoverySuppress
  ) {
    if (
      mem.hardSince !== null &&
      finite(mem.hardSince) &&
      now - mem.hardSince > 0.82 &&
      speedAbs < 0.50
    ) {
      requestRecovery = true;
    }

    if (
      noGoalProgress &&
      (
        loop3 ||
        repeatedCell
      ) &&
      (
        !mem.avoid ||
        now - mem.avoidStart > 3.0
      )
    ) {
      requestRecovery = true;
    }

    if (
      mem.avoid &&
      now - mem.avoidStart > 8.5 &&
      noGoalProgress &&
      loop5
    ) {
      requestRecovery = true;
    }

    if (
      !mem.avoid &&
      now - mem.lastMotionT > 7.0 &&
      (
        front < 2.30 ||
        Math.abs(goalAngle) > 110
      )
    ) {
      requestRecovery = true;
    }

    if (stationary) {
      requestRecovery = true;
    }
  }

  function recoveryOutput() {
    const sign =
      mem.recoverSign >= 0
        ? 1
        : -1;

    let drive = 0;
    let turnNorm = 0;
    let turnPower = 0;

    if (mem.recoverStage === 1) {
      drive = 0;
      turnNorm = 0.82 * sign;
      turnPower = 0.34;
    } else if (mem.recoverStage === 2) {
      drive = 0;
      turnNorm = 0.92 * sign;
      turnPower = 0.38;
    } else {
      drive = 0.36;

      turnNorm = clamp(
        goalTurn +
        0.22 * sign +
        0.28 * sideRepel +
        boundaryTurn,
        -1,
        1
      );

      if (front < 1.25) {
        turnNorm = clamp(
          turnNorm +
          mem.recoverSign * 0.38,
          -1,
          1
        );

        drive *= clamp(
          (front - 0.56) / 0.69,
          0,
          1
        );
      }

      if (sideEmergency) {
        if (emergencyTerm > 0) {
          turnNorm = Math.max(
            turnNorm,
            emergencyTerm
          );
        } else {
          turnNorm = Math.min(
            turnNorm,
            emergencyTerm
          );
        }
      }

      turnPower = 0.36;
    }

    if (front < 0.58) {
      drive = 0;
    }

    return send(
      drive - turnPower * turnNorm,
      drive + turnPower * turnNorm,
      true
    );
  }

  if (mem.recoverStage) {
    if (
      mem.recoverStage === 1 &&
      now >= mem.recoverUntil
    ) {
      mem.recoverStage = 2;
      mem.recoverUntil =
        now + (mem.recoverLong ? 1.70 : 1.42);
    }

    if (mem.recoverStage === 2) {
      const turned = Math.abs(
        wrap(heading - mem.recoverBaseHeading)
      );

      const turnGoal =
        mem.recoverLong
          ? 148
          : 112;

      if (
        (
          turned > turnGoal &&
          now - mem.recoverStart > 0.40
        ) ||
        now >= mem.recoverUntil
      ) {
        mem.recoverStage = 3;
        mem.recoverUntil =
          now + (mem.recoverLong ? 1.85 : 1.48);
      }
    }

    if (
      mem.recoverStage === 3 &&
      now >= mem.recoverUntil
    ) {
      mem.recoverStage = 0;
      mem.escapeSign = mem.recoverSign;
      mem.escapeUntil =
        now + (mem.recoverLong ? 2.4 : 1.75);
      mem.avoid = false;
      mem.avoidCooldown = now + 0.82;
      mem.plan = null;
      mem.planRetry = now + 0.30;
      mem.mapDirty = true;
      mem.lastMotionT = now;
      mem.lastGoalImprove = now;
      mem.bestTargetDist = targetDistance + 0.12;
      mem.recoverySuppress = now + 5.5;
    }

    if (mem.recoverStage) {
      return recoveryOutput();
    }
  }

  if (
    requestRecovery &&
    !mem.recoverStage
  ) {
    const closeToLast =
      finite(mem.lastRecoveryX) &&
      finite(mem.lastRecoveryY) &&
      now - mem.lastRecoveryT < 8.5 &&
      Math.hypot(
        x - mem.lastRecoveryX,
        y - mem.lastRecoveryY
      ) < 2.8;

    let sign;

    if (
      clearLeft > clearRight + 0.25
    ) {
      sign = 1;
    } else if (
      clearRight > clearLeft + 0.25
    ) {
      sign = -1;
    } else if (mem.avoid) {
      sign = mem.avoidSign;
    } else {
      sign = mem.bias >= 0 ? 1 : -1;
    }

    if (closeToLast) {
      sign = -(
        mem.lastRecoverySign >= 0
          ? 1
          : -1
      );
    }

    mem.recoverSign = sign;
    mem.recoverLong =
      closeToLast ||
      loop5 ||
      repeatedCell ||
      (
        mem.avoid &&
        now - mem.avoidStart > 8.0
      );

    mem.recoverStage = 1;
    mem.recoverStart = now;
    mem.recoverBaseHeading = heading;
    mem.recoverUntil = now + 0.28;

    mem.lastRecoveryT = now;
    mem.lastRecoveryX = x;
    mem.lastRecoveryY = y;
    mem.lastRecoverySign = sign;
    mem.recoverySuppress = now + 6.0;

    mem.avoid = false;
    mem.avoidCooldown = now + 0.85;
    mem.plan = null;
    mem.planRetry = now + 0.30;
    mem.mapDirty = true;
    mem.hardSince = null;
    mem.lastGoalImprove = now;
    mem.bestTargetDist = targetDistance + 0.10;

    mem.visit[currentCell] = Math.min(
      255,
      mem.visit[currentCell] + 18
    );

    return recoveryOutput();
  }

  let escapeActive =
    mem.escapeUntil > now &&
    targetDistance > 1.05;

  if (mem.escapeUntil <= now) {
    mem.escapeUntil = 0;
    escapeActive = false;
  }

  let turnNorm;

  if (mem.avoid) {
    const wallSide =
      mem.avoidSign > 0
