      front,
      sensed[3] + 0.45
    );
  }

  const outerLookLimit =
    speedAbs > 1.45
      ? 1.05
      : 0.70;

  if (sensed[0] < outerLookLimit) {
    front = Math.min(
      front,
      sensed[0] + 0.65
    );
  }

  if (sensed[4] < outerLookLimit) {
    front = Math.min(
      front,
      sensed[4] + 0.65
    );
  }

  let bx = 0;
  let by = 0;

  if (x < 1.35) bx += 1.35 - x;
  if (x > 38.65) bx -= x - 38.65;
  if (y < 1.35) by += 1.35 - y;
  if (y > 38.65) by -= y - 38.65;

  let boundaryTurn = 0;
  const boundaryMagnitude = Math.hypot(bx, by);

