  if (needPlan) {
    if (isLineClear(obs.x, obs.y, obs.targetX, obs.targetY)) {
      let gcx = clamp(Math.floor(obs.targetX / CS), 0, W - 1);
      let gcy = clamp(Math.floor(obs.targetY / CS), 0, H - 1);
      mem.path = [gcy * W + gcx];
      mem.lastPlanT = obs.t;
    } else {
      let path = aStar(obs.x, obs.y, obs.targetX, obs.targetY);
      if (path && path.length > 0) {
        mem.path = path;
        mem.lastPlanT = obs.t;
      } else {
        mem.path = null;
      }
    }
  }

  let wx = obs.targetX, wy = obs.targetY;
  if (mem.path && mem.path.length > 0) {
    let bestI = 0, bestD = Infinity;
    let limit = Math.min(mem.path.length, 140);
    for (let i = 0; i < limit; i++) {
      let idx = mem.path[i];
      let px = (idx % W + 0.5) * CS;
      let py = (Math.floor(idx / W) + 0.5) * CS;
      let d2 = (px - obs.x) * (px - obs.x) + (py - obs.y) * (py - obs.y);
      if (d2 < bestD) { bestD = d2; bestI = i; }
    }
    let look = bestI;
    let lookDist = minAll > 1.2 ? 0.9 : 0.55;
    for (let i = bestI; i < mem.path.length && i < bestI + 40; i++) {
      let idx = mem.path[i];
      let px = (idx % W + 0.5) * CS;
      let py = (Math.floor(idx / W) + 0.5) * CS;
      let d = Math.hypot(px - obs.x, py - obs.y);
      if (d >= lookDist) {
        if (isLineClear(obs.x, obs.y, px, py)) look = i;
        else look = Math.max(bestI, i - 1);
        break;
      }
      look = i;
    }
    let idx = mem.path[look];
    wx = (idx % W + 0.5) * CS;
    wy = (Math.floor(idx / W) + 0.5) * CS;
  }

  let distTarget = Math.hypot(obs.targetX - obs.x, obs.targetY - obs.y);
  if (distTarget < 1.0) {
    wx = obs.targetX;
    wy = obs.targetY;
  }

  let dxW = wx - obs.x;
  let dyW = wy - obs.y;
  let distW = Math.hypot(dxW, dyW);
  if (distW < 0.05) {
    wx = obs.targetX;
    wy = obs.targetY;
    dxW = wx - obs.x;
    dyW = wy - obs.y;
    distW = Math.hypot(dxW, dyW);
  }

  let desired = Math.atan2(dyW, dxW) / rad;
  let err = angDiff(desired, corrected);

  let rightMin = Math.min(r0, r1);
  let leftMin = Math.min(r3, r4);
  let openRight = r0 + r1;
  let openLeft = r3 + r4;

  let sideTurn = 0;
  if (rightMin < 0.55) sideTurn += (0.55 - rightMin) * 1.2;
  if (leftMin < 0.55) sideTurn -= (0.55 - leftMin) * 1.2;
  if (r1 < 0.45) sideTurn += (0.45 - r1) * 1.5;
  if (r3 < 0.45) sideTurn -= (0.45 - r3) * 1.5;
  if (r2 < 1.0) sideTurn += (openLeft - openRight) * 0.5;
  sideTurn = clamp(sideTurn, -1.0, 1.0);

  if (minAll < 0.4 || r2 < 0.55) {
    mem.avoidDir = openLeft > openRight ? 1 : -1;
    mem.avoidTimer = 0.4;
  }
  if (mem.avoidTimer > 0) {
    mem.avoidTimer -= dt;
    sideTurn += mem.avoidDir * 0.7;
    sideTurn = clamp(sideTurn, -1.3, 1.3);
  }

  let turn = err * 0.012 + sideTurn - mem.hRate * 0.0015;
  turn = clamp(turn, -0.9, 0.9);

  let base = 0.8;
  let absErr = Math.abs(err);

  if (absErr > 20) base = Math.min(base, 0.65);
  if (absErr > 40) base = Math.min(base, 0.5);
  if (absErr > 70) base = Math.min(base, 0.35);
  if (absErr > 110) base = Math.min(base, 0.2);

  if (r2 < 2.0) base = Math.min(base, 0.6);
  if (r2 < 1.4) base = Math.min(base, 0.45);
  if (r2 < 1.0) base = Math.min(base, 0.3);
  if (r2 < 0.7) base = Math.min(base, 0.15);
  if (r2 < 0.5) base = Math.min(base, -0.1);

  if (minAll < 0.8) base = Math.min(base, 0.5);
  if (minAll < 0.55) base = Math.min(base, 0.35);
  if (minAll < 0.4) base = Math.min(base, 0.2);
  if (minAll < 0.3) base = Math.min(base, 0.0);

  if (distTarget < 1.5) base = Math.min(base, 0.5);
  if (distTarget < 1.0) base = Math.min(base, 0.35);
  if (distTarget < 0.7) base = Math.min(base, 0.25);

  if (r2 < 0.55 && obs.speed > 0.2) base = -0.2;

  if (Math.abs(base) > 0.1 && Math.abs(obs.speed) < 0.06) {
    mem.stuck += dt;
  } else {
    mem.stuck = Math.max(0, mem.stuck - dt * 2.0);
  }

  if (mem.escapeTimer > 0) {
    mem.escapeTimer -= dt;
    base = -0.3;
    turn = mem.escapeDir * 0.6;
  } else if (mem.stuck > 1.0) {
    mem.escapeTimer = 0.6;
    mem.escapeDir = openLeft > openRight ? 1 : -1;
    mem.stuck = 0;
    base = -0.3;
    turn = mem.escapeDir * 0.6;
  }

  let left = clamp(base - turn, -1, 1);
  let right = clamp(base + turn, -1, 1);

  if (Math.abs(left) < 0.08 && Math.abs(right) < 0.08) {
    left = 0;
    right = 0;
  } else {
    if (left > 0 && left < 0.1) left = 0.1;
    if (right > 0 && right < 0.1) right = 0.1;
    if (left < 0 && left > -0.1) left = -0.1;
    if (right < 0 && right > -0.1) right = -0.1;
  }

  mem.lastTurn = turn;
  return { left: left, right: right };
}

function act(obs, mem) {
  const rad = Math.PI / 180;
  const CS = 0.4;
  const W = 100, H = 100;
  const RAY_ANGLES = [-60, -30, 0, 30, 60];

  function clamp(v, lo, hi) { return v < lo ? lo : (v > hi ? hi : v); }
  function angDiff(a, b) {
    let d = a - b;
    while (d > 180) d -= 360;
    while (d < -180) d += 360;
    return d;
  }
  function normDeg(a) {
    while (a > 180) a -= 360;
    while (a < -180) a += 360;
    return a;
  }

  if (!mem.init) {
    mem.init = true;
    const total = W * H;
    mem.grid = new Uint8Array(total);
    mem.bias = 0;
    mem.hRate = 0;
    mem.lastCorrected = obs.heading;
    mem.lastX = obs.x;
    mem.lastY = obs.y;
    mem.lastT = obs.t;
    mem.courseX = obs.x;
    mem.courseY = obs.y;
    mem.courseT = obs.t;
    mem.stuck = 0;
    mem.escapeTimer = 0;
    mem.escapeDir = 1;
    mem.avoidTimer = 0;
    mem.avoidDir = 1;
    mem.lastTarget = obs.targetIndex;
    mem.path = null;
    mem.lastPlanT = -999;
    mem.lastTurn = 0;
    mem.gScore = new Float32Array(total);
    mem.parent = new Int32Array(total);
    mem.visitStamp = new Int32Array(total);
    mem.closedStamp = new Int32Array(total);
    mem.heapI = new Int32Array(total * 4);
    mem.heapF = new Float32Array(total * 4);
    mem.stamp = 0;
  }

  let dt = obs.t - mem.lastT;
  if (!(dt > 0) || dt > 0.5) dt = 0.05;

  // Slow compass-bias estimate from straight movement.
  if (obs.t - mem.courseT > 0.3) {
    const cdx = obs.x - mem.courseX;
    const cdy = obs.y - mem.courseY;
    const cdist = Math.hypot(cdx, cdy);
    if (cdist > 0.15 && Math.abs(obs.speed) > 0.3 && Math.abs(mem.hRate) < 30 && Math.abs(mem.lastTurn) < 0.2) {
      const course = Math.atan2(cdy, cdx) / rad;
      const sample = angDiff(obs.heading, course);
      if (Math.abs(sample) < 60) {
        mem.bias = mem.bias * 0.98 + sample * 0.02;
      }
    }
    mem.courseX = obs.x;
    mem.courseY = obs.y;
    mem.courseT = obs.t;
  }

  const corrected = normDeg(obs.heading - mem.bias);
  if (mem.lastCorrected !== undefined) {
    const rawRate = angDiff(corrected, mem.lastCorrected) / dt;
    mem.hRate = mem.hRate * 0.8 + rawRate * 0.2;
  }
  mem.lastCorrected = corrected;
  mem.lastX = obs.x;
  mem.lastY = obs.y;
  mem.lastT = obs.t;

  const rays = obs.rays || [10, 10, 10, 10, 10];
  let r0 = clamp(typeof rays[0] === 'number' ? rays[0] : 10, 0, 10);
  let r1 = clamp(typeof rays[1] === 'number' ? rays[1] : 10, 0, 10);
  let r2 = clamp(typeof rays[2] === 'number' ? rays[2] : 10, 0, 10);
  let r3 = clamp(typeof rays[3] === 'number' ? rays[3] : 10, 0, 10);
  let r4 = clamp(typeof rays[4] === 'number' ? rays[4] : 10, 0, 10);
  if (typeof obs.distanceAhead === 'number') r2 = clamp(obs.distanceAhead, 0, 10);
  const minAll = Math.min(r0, r1, r2, r3, r4);

  function markFreePoint(x, y) {
    const cx = Math.floor(x / CS);
    const cy = Math.floor(y / CS);
    if (cx >= 0 && cx < W && cy >= 0 && cy < H) {
      const idx = cy * W + cx;
      if (mem.grid[idx] !== 2) mem.grid[idx] = 1;
    }
  }

  function markObstacle(x, y) {
    const cx = Math.floor(x / CS);
    const cy = Math.floor(y / CS);
    for (let dx = -1; dx <= 1; dx++) {
      for (let dy = -1; dy <= 1; dy++) {
        if (Math.abs(dx) + Math.abs(dy) > 1) continue;
        const nx = cx + dx;
        const ny = cy + dy;
        if (nx >= 0 && nx < W && ny >= 0 && ny < H) {
          mem.grid[ny * W + nx] = 2;
        }
      }
    }
  }

  markFreePoint(obs.x, obs.y);
  const rayDists = [r0, r1, r2, r3, r4];
  for (let i = 0; i < 5; i++) {
    const d = rayDists[i];
    const a = (corrected + RAY_ANGLES[i]) * rad;
    const ca = Math.cos(a);
    const sa = Math.sin(a);
    for (let dist = 0.2; dist < d - 0.3; dist += 0.4) {
      markFreePoint(obs.x + ca * dist, obs.y + sa * dist);
    }
    if (d < 9.5) {
      markObstacle(obs.x + ca * d, obs.y + sa * d);
    }
  }

  function isBlocked(cx, cy) {
    if (cx < 0 || cx >= W || cy < 0 || cy >= H) return true;
    const wx = (cx + 0.5) * CS;
    const wy = (cy + 0.5) * CS;
    if (wx < 0.35 || wx > 39.65 || wy < 0.35 || wy > 39.65) return true;
    return mem.grid[cy * W + cx] === 2;
  }

  function isLineClear(x1, y1, x2, y2) {
    const dist = Math.hypot(x2 - x1, y2 - y1);
    const steps = Math.ceil(dist / 0.2);
    if (steps < 1) return true;
    for (let i = 1; i < steps; i++) {
      const t = i / steps;
      const x = x1 + (x2 - x1) * t;
      const y = y1 + (y2 - y1) * t;
      if ((x - x1) * (x - x1) + (y - y1) * (y - y1) < 0.2) continue;
      const cx = Math.floor(x / CS);
      const cy = Math.floor(y / CS);
      if (isBlocked(cx, cy)) return false;
    }
    return true;
  }

  function heuristic(cx, cy, gx, gy) {
    const dx = Math.abs(cx - gx);
    const dy = Math.abs(cy - gy);
    return (dx + dy) + (1.41421356 - 2) * Math.min(dx, dy);
  }

  function aStar(sx, sy, gx, gy) {
    let scx = clamp(Math.floor(sx / CS), 0, W - 1);
    let scy = clamp(Math.floor(sy / CS), 0, H - 1);
    let gcx = clamp(Math.floor(gx / CS), 0, W - 1);
    let gcy = clamp(Math.floor(gy / CS), 0, H - 1);

    if (isBlocked(gcx, gcy)) {
      let best = null;
      let bestD = Infinity;
      for (let r = 1; r <= 15; r++) {
        for (let dx = -r; dx <= r; dx++) {
          for (let dy = -r; dy <= r; dy++) {
            if (Math.abs(dx) !== r && Math.abs(dy) !== r) continue;
            const nx = gcx + dx;
            const ny = gcy + dy;
            if (nx < 0 || nx >= W || ny < 0 || ny >= H) continue;
            if (!isBlocked(nx, ny)) {
              const d = dx * dx + dy * dy;
              if (d < bestD) {
                bestD = d;
                best = [nx, ny];
              }
            }
          }
        }
        if (best) break;
      }
      if (!best) return null;
      gcx = best[0];
      gcy = best[1];
    }

    const startIdx = scy * W + scx;
    const goalIdx = gcy * W + gcx;
    if (startIdx === goalIdx) return [startIdx];

    let stamp = ++mem.stamp;
    if (stamp > 1000000) {
      mem.visitStamp.fill(0);
      mem.closedStamp.fill(0);
      stamp = mem.stamp = 1;
    }

    let heapSize = 0;
    function push(idx, f) {
      let i = heapSize++;
      while (i > 0) {
        const p = (i - 1) >> 1;
        if (mem.heapF[p] <= f) break;
        mem.heapI[i] = mem.heapI[p];
        mem.heapF[i] = mem.heapF[p];
        i = p;
      }
      mem.heapI[i] = idx;
      mem.heapF[i] = f;
    }
    function pop() {
      const res = mem.heapI[0];
      heapSize--;
      if (heapSize > 0) {
        const lastI = mem.heapI[heapSize];
        const lastF = mem.heapF[heapSize];
        let i = 0;
        while (true) {
          const l = 2 * i + 1;
          const r = 2 * i + 2;
          let s = i;
          if (l < heapSize && mem.heapF[l] < lastF) s = l;
          if (r < heapSize && mem.heapF[r] < (s === i ? lastF : mem.heapF[s])) s = r;
          if (s === i) break;
          mem.heapI[i] = mem.heapI[s];
          mem.heapF[i] = mem.heapF[s];
          i = s;
        }
        mem.heapI[i] = lastI;
        mem.heapF[i] = lastF;
      }
      return res;
    }

    mem.visitStamp[startIdx] = stamp;
    mem.gScore[startIdx] = 0;
    mem.parent[startIdx] = -1;
    push(startIdx, heuristic(scx, scy, gcx, gcy));

    let iter = 0;
    let found = false;
    let bestIdx = startIdx;
    let bestH = heuristic(scx, scy, gcx, gcy);

    while (heapSize > 0 && iter < 8000) {
      const cur = pop();
      if (mem.closedStamp[cur] === stamp) continue;
      mem.closedStamp[cur] = stamp;
      if (cur === goalIdx) {
        found = true;
        break;
      }
      const cx = cur % W;
      const cy = (cur - cx) / W;
      const hh = heuristic(cx, cy, gcx, gcy);
      if (hh < bestH) {
        bestH = hh;
        bestIdx = cur;
      }

      for (let dx = -1; dx <= 1; dx++) {
        for (let dy = -1; dy <= 1; dy++) {
          if (dx === 0 && dy === 0) continue;
          const nx = cx + dx;
          const ny = cy + dy;
          if (nx < 0 || nx >= W || ny < 0 || ny >= H) continue;
          if (isBlocked(nx, ny)) continue;
          if (dx !== 0 && dy !== 0) {
            if (isBlocked(cx + dx, cy) || isBlocked(cx, cy + dy)) continue;
          }
          const nIdx = ny * W + nx;
          if (mem.closedStamp[nIdx] === stamp) continue;
          let cost = (dx !== 0 && dy !== 0) ? 1.41421356 : 1.0;
          if (mem.grid[nIdx] === 0) cost *= 1.3;
          const tentative = mem.gScore[cur] + cost;
          const oldG = (mem.visitStamp[nIdx] === stamp) ? mem.gScore[nIdx] : Infinity;
          if (tentative < oldG) {
            mem.visitStamp[nIdx] = stamp;
            mem.gScore[nIdx] = tentative;
            mem.parent[nIdx] = cur;
            push(nIdx, tentative + heuristic(nx, ny, gcx, gcy));
          }
        }
      }
      iter++;
    }

    const end = found ? goalIdx : bestIdx;
    const path = [];
    let cur = end;
    while (cur !== -1) {
      path.push(cur);
      if (cur === startIdx) break;
      cur = mem.parent[cur];
    }
    path.reverse();
    return path;
  }

  if (obs.targetIndex !== mem.lastTarget) {
    mem.lastTarget = obs.targetIndex;
    mem.path = null;
    mem.lastPlanT = -999;
    mem.stuck = 0;
    mem.escapeTimer = 0;
  }

  const distTarget = Math.hypot(obs.targetX - obs.x, obs.targetY - obs.y);
  let wx = obs.targetX;
  let wy = obs.targetY;

  if (isLineClear(obs.x, obs.y, obs.targetX, obs.targetY)) {
    mem.path = null;
  } else {
    let needPlan = false;
    if (obs.t - mem.lastPlanT > 1.5) needPlan = true;
    if (!mem.path || mem.path.length === 0) {
      if (obs.t - mem.lastPlanT > 1.0) needPlan = true;
    }
    if (mem.path && mem.path.length > 0) {
      const last = mem.path[mem.path.length - 1];
      const lx = (last % W + 0.5) * CS;
      const ly = (Math.floor(last / W) + 0.5) * CS;
      if (Math.hypot(lx - obs.targetX, ly - obs.targetY) > 2.0 && obs.t - mem.lastPlanT > 0.5) {
        needPlan = true;
      }
    }
    if (needPlan) {
      const path = aStar(obs.x, obs.y, obs.targetX, obs.targetY);
      mem.path = path;
      mem.lastPlanT = obs.t;
    }

    if (mem.path && mem.path.length > 0) {
      let bestI = 0;
      let bestD = Infinity;
      const limit = Math.min(mem.path.length, 80);
      for (let i = 0; i < limit; i++) {
        const idx = mem.path[i];
        const px = (idx % W + 0.5) * CS;
        const py = (Math.floor(idx / W) + 0.5) * CS;
        const d2 = (px - obs.x) * (px - obs.x) + (py - obs.y) * (py - obs.y);
        if (d2 < bestD) {
          bestD = d2;
          bestI = i;
        }
      }
      let look = bestI;
      for (let i = bestI; i < mem.path.length && i < bestI + 30; i++) {
        const idx = mem.path[i];
        const px = (idx % W + 0.5) * CS;
        const py = (Math.floor(idx / W) + 0.5) * CS;
        if (isLineClear(obs.x, obs.y, px, py)) {
          look = i;
        } else {
          break;
        }
      }
      const idx = mem.path[look];
      wx = (idx % W + 0.5) * CS;
      wy = (Math.floor(idx / W) + 0.5) * CS;
    }
  }

  if (distTarget < 1.2) {
    wx = obs.targetX;
    wy = obs.targetY;
  }

  let dxW = wx - obs.x;
  let dyW = wy - obs.y;
  let distW = Math.hypot(dxW, dyW);
  if (distW < 0.05) {
    wx = obs.targetX;
    wy = obs.targetY;
    dxW = wx - obs.x;
    dyW = wy - obs.y;
    distW = Math.hypot(dxW, dyW);
  }

  const desired = Math.atan2(dyW, dxW) / rad;
  const err = angDiff(desired, corrected);

  const rightMin = Math.min(r0, r1);
  const leftMin = Math.min(r3, r4);
  const openRight = r0 + r1;
  const openLeft = r3 + r4;

  let sideTurn = 0;
  if (rightMin < 0.55) sideTurn += (0.55 - rightMin) * 0.8;
  if (leftMin < 0.55) sideTurn -= (0.55 - leftMin) * 0.8;
  if (r1 < 0.4) sideTurn += (0.4 - r1) * 1.0;
  if (r3 < 0.4) sideTurn -= (0.4 - r3) * 1.0;
  if (r2 < 1.0) sideTurn += (openLeft - openRight) * 0.3;
  sideTurn = clamp(sideTurn, -0.8, 0.8);

  if (minAll < 0.45 || r2 < 0.6) {
    mem.avoidDir = openLeft > openRight ? 1 : -1;
    mem.avoidTimer = 0.4;
  }
  if (mem.avoidTimer > 0) {
    mem.avoidTimer -= dt;
    sideTurn += mem.avoidDir * 0.5;
    sideTurn = clamp(sideTurn, -1.0, 1.0);
  }

  let turn = err * 0.008 + sideTurn - mem.hRate * 0.002;
  turn = clamp(turn, -0.8, 0.8);

  let base = 0.85;
  const absErr = Math.abs(err);

  if (absErr > 30) base = Math.min(base, 0.7);
  if (absErr > 60) base = Math.min(base, 0.5);
  if (absErr > 90) base = Math.min(base, 0.35);
  if (absErr > 120) base = Math.min(base, 0.25);

  if (r2 < 2.0) base = Math.min(base, 0.6);
  if (r2 < 1.4) base = Math.min(base, 0.45);
  if (r2 < 1.0) base = Math.min(base, 0.3);
  if (r2 < 0.7) base = Math.min(base, 0.15);
  if (r2 < 0.5) base = Math.min(base, -0.1);

  if (minAll < 0.8) base = Math.min(base, 0.5);
  if (minAll < 0.6) base = Math.min(base, 0.35);
  if (minAll < 0.45) base = Math.min(base, 0.2);
  if (minAll < 0.35) base = Math.min(base, 0.0);

  if (distTarget < 1.5) base = Math.min(base, 0.5);
  if (distTarget < 1.0) base = Math.min(base, 0.35);
  if (distTarget < 0.7) base = Math.min(base, 0.25);

  if (Math.abs(turn) > 0.6) base = Math.min(base, 0.4);

  if (Math.abs(base) > 0.1 && Math.abs(obs.speed) < 0.05) {
    mem.stuck += dt;
  } else {
    mem.stuck = Math.max(0, mem.stuck - dt * 2);
  }

  if (mem.escapeTimer > 0) {
    mem.escapeTimer -= dt;
    base = -0.25;
    turn = mem.escapeDir * 0.5;
  } else if (mem.stuck > 0.8) {
    mem.escapeTimer = 0.5;
    mem.escapeDir = openLeft > openRight ? 1 : -1;
    mem.stuck = 0;
    base = -0.25;
    turn = mem.escapeDir * 0.5;
  }

  let left = clamp(base - turn, -1, 1);
  let right = clamp(base + turn, -1, 1);

  if (Math.abs(left) < 0.08 && Math.abs(right) < 0.08) {
    left = 0;
    right = 0;
  } else {
    if (left > 0 && left < 0.1) left = 0.1;
    if (right > 0 && right < 0.1) right = 0.1;
    if (left < 0 && left > -0.1) left = -0.1;
    if (right < 0 && right > -0.1) right = -0.1;
  }

  mem.lastTurn = turn;
  return { left: left, right: right };
